window.__D("text/shaarei-teshuva/c004",{"p":[[2500660519,"בכנ\"י בתפלה כאשר מתקרבים בכל פנימיו' רצונם שבנפש' רק לה' לבדו ואין זר אתו דהיינו לבטל כל הרצונות הזרות הנכרים המקושרים בעניני הבלי העוה\"ז למאוס בהם לגמרי ולא עוד אלא שיהי' פנימיו' הרצון של הנפש בלתי לה' לבדו דוקא וכמ\"ש מי לי בשמי' ועמך לא חפצתי כו' דהיינו גם הרצון בתענוג העליון האלקי בג\"ע ועוה\"ב שהנשמות נהנין כו' גם בזה אין עיקר החפץ והרצון גם שהוא שכר הנשמות אבל קבלת פרס זה לא היה בו עיקר רצון הנפש האלקי' בלתי להוי\"ה לבדו במהותו ועצמותו דוקא בהיות שכל מקור חיות אור האלקי שבג\"ע ועוה\"ב אינו רק מבחי' אות א' שבמחשבה ודיבור העליון כמ\"ש ז\"ל ביו\"ד נברא העוה\"ב כו' אבל דביקות הרצון שבפנימיות הנפש אינו רק במהות ועצמות אא\"ס לבדו דוקא ולא בבחי' הארתו באותיות לבד כו' וז\"ש מי לי בשמים שהוא בחי' מקיפים דבריאה שבג\"ע העליון דבריאה גם לא בג\"ע התחתון שבארץ כ\"א במהותו ועצמותו דוקא כלה שארי ולבבי כו' וז\"ש את פניך ה' אבקש פניך דוקא בחי' פנימיות ועצמות אא\"ס שבפנימיות רצון העליון עצמו שזהו בחי' פנימיות דשם הוי\"ה וז\"ש את פניך הוי\"ה כו' שלמעלה מבחי' הארה חיצוניות דשם הוי\"ה באחד להיות בבחי' סובב וממלא כו' כנ\"ל והיינו כמים הפנים כו' משום דאתדל\"ת מכנ\"י מלמטה למעלה בחי' קרבתם לפני ה' בעבודה שבלב בק\"ש ותפלה בא מבחי' פנימיות הרצון שבנקודת הלב בביטול כל רצון זר רק להוי\"ה לבדו בבחי' פנימי' וז\"ש לך אמר לבי בקשו פני ואז ממילא את פניך ה' אבקש כו' בחי' פנים בפנים כי רוח אייתי רוח כו' וזהו הנק' יחוד פנים בפנים שהמשפיע והמקבל מתקשרים זע\"ז בכל פנימית שבנפשם בחי' פנימית המקבל אל המשפיע ובחי' פנימיות המשפיע אל המקבל בשעת יחודם כו' (וכמ\"כ היה במ\"ת דכתי' פב\"פ דיבר הוי\"ה עמכם כו' לפי שעל כל דיבור ודיבור פרחה נשמתן כו' שהרי בכל פנימיות הרצון קיבלו עליהם כשאמרו נעשה ונשמע כו' וא\"כ הרי יובן מכ\"ז בק\"ש באמרו ואהבת בכל לבבך בשני יצריך שזהו לבטל כל הרצונות הזרות"],[2500660520,"עד שימאס בחיי הבלי העוה\"ז ולא יאיר רצונו בהן רק בבחי' אחוריים בהכרח בע\"כ מפני צורך קיום הנפש לבד כו' וע\"ד שארז\"ל שיהיה תורתו קבע ומלאכתו עראי דהכוונה גם על בחי' הפנימיות שבדבר זה שהוא מפני שפנימיות נפשו מקושר בהוי\"ה אחד ע\"כ תורתו קבע בקביעות נפשו הפנימיות ומלאכתו בעניני עוה\"ז עראי דרך חיצוניות כמתעסק בעלמא רק מפני ההכרח כו' ומאחר שפונה כל פנימיות שבנפשו להוי\"ה באמרו בכל לבבך ובכל נפשך אז ממילא כמים הפנים כו' הקב\"ה פונה אליו ג\"כ בבחי' פנים שלו כמו יאר ה' פניך אליך אלי\"ך לכל פרט ניצוץ שבכאו\"א מישראל מבחי' פנימיות דהוי\"ה שלמעלה מהיות מקור להתהוות מקומו של עולם כו' וא\"כ הרי מובן עכ\"פ שע\"י בחי' אהבה דבכל נפשך כו' נעשה בחי' החזרת היחוד פב\"פ דוקא גם שהיה תחלה בבחי' אב\"א כו' ולא היה נעשה זה בפסוק ראשון לבד במס\"נ של הנשמה מצד טבעה באחד לפי שישראל עלה במחשבה וח\"ע כו' שאין זה עדיין בבחי' פנימיות הרצון שלמעלה מן השכל כו' אלא דווקא ע\"י מס\"נ דאהבה ורצון שלמעלה מן השכל רק שנולד מצד התלבשות הרצון בשכל כנ\"ל באריכות וד\"ל:\n(מח) <b>וזהו</b> מ\"ש בפע\"ח דסיבת היחוד שבק\"ש בחזרת פנים בפנים כו' הוא ע\"י דו\"ר שכליים שאחר שמע ישראל כו' שהחכמה והמוחין שמתבונן באחדות הוי\"ה כו' גורם תולדות הרצון הפנימית כו' כנ\"ל ולא ע\"י דו\"ר טבעיי' כו' שאין בזה בחי' הרצון הפנימי כי הלא אינו מסלק כל הרצון זר למאוס ברע כו' מאחר שהוא בלא דעת והתבוננות דסובב להיות הרצון רק לה' לבדו כו' וד\"ל. אך הנה אהבה ורצון דבכל נפשך הוא בא בבחי' אור ישר מלמעלה למטה דהיינו ע\"י אתדל\"ת בהכנת הנפ\"א בהתבוננות דסובב כו' לפי שיעור מדריגת' תדבק נפשה להכלל באור א\"ס כו' מחשבה שלה תדבק במחשבה עליונה ודיבור בדיבור כו' וכפי ערך העלאת מ\"נ כן נמשך בחי' אור ישר בחי' ירידה והמשכת אור האלקי בנפשו כו' בבחי' פב\"פ"],[2500660521,"כו' כנ\"ל. אבל בחי' אהבת בכל מאדך היא אהבה רבה הבאה מלמטה למעלה בבחי' אור חוזר מלמטה למעלה דוקא וזהו שרש בחי' התשובה שהיא ג\"כ בחי' אור חוזר כידוע:\n<b>וביאור</b> הדברים הנה התשובה היא גורמת בחי' החזרת היחוד פב\"פ דוקא יותר מן הק\"ש כו' שהרי מקרא מפורש נאמר השיבנו ה' אליך ונשובה פי' השיבנו בתחלה שהיא תשובה ראשונה ואח\"כ ונשובה בחי' תשובה שנית ולכאורה למה צריך לב' תשובות אך הענין הוא דבחי' תשובה הא' הוא רק כח ההחזרה מן הריחוק שנתרחקו ופנו עורף וכמ\"ש אתה הסיבות את לבם אחורנית כו' ולזה אמר השיבנו ה' אליך שהתשובה זאת מאת ה' היא להשיב את הנדח והמרוחק כמ\"ש נדחי ישראל יכנס כו' וזהו אליך כדי שיפנו בבחי' פנים אליך צריך להשיבם תחלה מן הריחוק הגדול שנתרחקו ועומדים בבחי' אחוריים כו' וזהו הנקרא תשובה תתאה כו' וכמ\"ש רז\"ל בת קול מכרזת בכל יום שובו בנים שובבים כו' וכרוז זה פועל התעוררות תשובה בעולם להחזירם מן הריחוק כמו שאמר שובו בנים שובבים כו' אך אח\"כ ונשובה לעמוד בבחי' פב\"פ שהוא בחי' תשובה עילאה שזהו בחי' פנימיות הרצון והתשוקה לידבק וליכלל בה' אחד ותשובה זו באה בכנ\"י מצד עצמם כמ\"ש ונשובה כו' והיינו בחי' אהבת בכל מאודך שהיא בלי גבול כו' ולכך אמרו דבע\"ת גדולים מצדיקים גמורים דצד\"ג בבחי' אהבה דבכל נפשך ע\"י ההתבוננות דשמע ישראל כנ\"ל הרי בא בחי' גילוי אור א\"ס מלמעלה למטה בשיעור ומדה עכ\"פ לפי ערך הכנת הנפש ברצון דמס\"נ אע\"פ שהוא למעלה מן השכל כנ\"ל מ\"מ גם בחי' הארת פנימית דהויה ע\"י העלאת מ\"נ זה אשר בא ג\"כ בבחי' רצון העליון שלמעלה מבחי' מחשבה וחכמה כו' הנה הוא נמשך לפי המדה של המקבל דהיינו לפי אופן בחי' הפנימיות רצון של המקבל וזהו הנקרא בחי' אור ישר שנמשך בבחי' המשכה מוגבלת לפי אופן כלי המקבל כו' משא\"כ בחי' אור חוזר דתשובה שגורם אהבה דבכל מאודך שהיא בלי גבול כלל והענין הוא כי"],[2500660522,"בחי' התשובה הבאה מעומקא דלבא ביותר הרי ידוע שזהו בחי' רצון ואהבה ותשוקה רבה בתגבורת גדולה כ\"כ בלב הנק' נקודת הלב עד אשר לא יכילנו כלי הלב והמוח כלל וזהו הנק' אור חוזר שמפני שלא יוכל להתיישב בכלי המוח והלב לעוצם התגבורת בהתפעלות ברצון פנימי כ\"כ שאין בכח המוח והלב להכילו ולהחזיקו אשר ע\"כ אור זה חוזר למעלה דהיינו מה שנשאר האור של הרצון ואה\"ר זאת בבחי' מקיף על המוח והלב וזהו הנק' מקיף דאור חוזר כידוע וד\"ל. והנה בחי' אור חוזר זה חוזר לקדמותו דהיינו למעלה מעלה בבחי' העצמות ממש שהוא למעלה גם מבחי' מסירת נפש דבכל נפשך הנ\"ל להיות דמסירת נפש דבכל נפשך הוא בבחי' הרצון עכ\"פ רק שהוא בחי' פנימיות הרצון אבל גם מהות הרצון אינו רק בחי' המשכה אחת מעצמות הנפש אע\"פ שהיא המשכה עצמית מעצמות הנפש כידוע אבל אין זה עצמות הנפש ממש רק חלק ממנה לבד הוא שנמשך ברצון וגם בפנימיות הרצון הזה אין בו רק חלק קטן כניצוץ הנבדל מן השלהבת כו' שהרי עצמות הנפש ממש הוא שנק' בעל הרצון שממנה נמשכו כל הרצונות הפנימיות ג\"כ ובאמת אין זה כדמיון הניצוץ לגבי השלהבת שמהות א' הן עכ\"פ רק שזה בקטנות וזה בגדלות כו' אבל מהות הרצון לגבי עצם הנפש אין לו דמיון במהות כלל כי הרי אנו רואים שהרצון הוא בחי' התפעלות שהרי מתפעל ברצון וחשק לדבר מה וא\"כ יש בזה בחי' הרכבה ושינוי כמו שאנו רואים שמתפעל ברצון לרצות כך ולא כך הרי יש שינוי שבאופן אחר לא יתפעל ברצון כלל או לדבר אחר אין לו רצון זה כלל אלא דוקא לדבר זה יש לו התפעלות הרצון וא\"כ רצון זה בא בבחי' הרכבה שמורכב בדבר מה וכל בחי' מורכב יש בו שינויים רבים ולפ\"ז גם בעיקר המשכת מהות הרצון יש בו ג' אלה הרכבה ושינוי והתפעלות והא בהא תליא כידוע וכל זה אינו בעצמו' מהות הנפש כלל כי ידוע דעצמות מהות הנפש פשוטה מושללת מכל בחי' הרכבה ושינוי והתפעלות כי היא אור פשוט וכאשר תבא לכלל בחי' התפעלות ברצון שזהו בבחי' מורכב שיפול"],[2500660523,"בו שינוי ותמורות אין זה מבחי' עצמותה כלל רק שמתצמצמת בעצמותה ומהותה לבא לבחי' מהות התפעלות הרצון הזה כו' וד\"ל. וזהו הנק' בעל הרצון שממנו מתצמצם בחי' התפעלות רצונות רבים ואע\"פ שנק' מקור כל הרצונות הבאים בהתפעלות אבל הוא עצמו שנק' בעל הרצון אינו בגדר בחי' התפעלות הרצון כלל בו רק עצם פשוט לבד נבדל ממהות הרצון לגמרי וד\"ל. וא\"כ הרי מובן בבחי' התפעלות הרצון דבכל נפשך אין זה עצמות ומהות הנפש ממש רק בחי' המשכה עצמיות שנמשך מעצמות מהות הנפש שהוא פנימיות הרצון הנק' רצון פשוט שלמעלה מהרכבת השכל והטעם אבל אין זה ערך לגבי בעל הרצון הפשוט הזה שלמעלה מבחי' ומהות התפעלות רצון כלל כנ\"ל. אך אהבה דבכל מאדך שהיא בלי גבול כלל היינו בבחי' עצמות ומהות הנפש ממש שנק' בעל הרצון שלמעלה מבחי' רצון לגמרי כנ\"ל דהיינו שכל עצמיות הנפש תכלה ותכסוף לצאת ולידבק ולא בבחי' רצון לבד וע\"כ נק' מאדך בלי גבול שאין אהבה רבה כזאת באה מבחי' גבול כחות הנפש ברצון וכה\"ג אלא בכל בחי' עצמותה שהיא היולית בלתי מוגבלת כלל אך הנה בחי' התפעלות כל עצמיות הנפש מכל וכל כו' א\"א להיות כ\"א בבחי' א\"ח אל העצמות שזהו כאשר לא יכיל כלי הנפש להחזיק ההתפעלות כי רב הוא למעלה מצמצום כלי כחות הנפש כמו השכל והלב שאז בהכרח שישאר ההתפעלות כזאת בבחי' מקיף על השכל והרצון ג\"כ דהיינו בעצמות הנפש בעל הרצון כו' וזאת המדריגה אינו אלא ע\"י בעלי תשובה דוקא יותר מע\"י צדיקים גמורים כנ\"ל לפי שבע\"ת היה רחוק מאד מאד מאור פני מלך חיים כי ע\"י עונותיו הרבים נתרחק בתכלית הריחוק העצום ולזאת יתמרמר בנפשו ביותר על עוצם ריחוקו עד אשר תשובתו לה' באה מעומקא דלבא ביותר כמו ר\"א בן דורדייא שיצאה נשמתו בבכייה כו' וכה\"ג והוא בחי' תגבורת התשוקה להדבק בה' בכל נקודת הלב שלמעלה מהכיל בכלי המוח והלב כלל וכלל והיינו מ\"ש בזהר דבע\"ת משכי לי' לקב\"ה בחילא יתיר פי' חילא יתיר הוא עוצם הכח"],[2500660524,"החזק שבעצמות הנפש שא\"א למוח ולב להכילו כלל וזהו הנק' בחי' אור חוזר והוא מצד בחי' הריחוק שמחמתו יתפעל בנקודת הלב אשר אין זה בצדיקי' גמורי' שהתפעלות' רק מצד השגתם והתענגם על ה' בתורה ותפלה גם בהתפעלות דבכל נפשך בק\"ש אין זה בכל נקודת עצמות הנפש רק בחי' אור הנמשך מעצמות הנפש שהוא הרצון משא\"כ תשוקת הבע\"ת שהוא בבחי' כליון הנפש כמ\"ש כלתה נפשי כמו רבי אלעזר בן דורדייא הנ\"ל וד\"ל. וזהו השיבנו ה' אליך ונשובה פי' השיבנו ה' זהו בחי' התעוררות תשובה שמעוררים מלמעלה שיוחזרו כנ\"י בבחי' פב\"פ וזהו ונשובה מעצמם בבחי' אהבת בכל מאדך כו' ונמצא שגם שהיה תחלה בבחי' אב\"א בא סיבת ההחזרה בבחי' פב\"פ ע\"י התעוררו' תשובה מלמעלה כמ\"ש השיבנו הוי\"ה אליך כו' ואז ממילא ונשובה וזהו סותר למ\"ש למעלה דהשיבנו הוא רק תשובה תתאה ומן הריחוק לבד ונשובה הוא תשובה עלאה דפב\"פ כו' ולכאורה איך מתש\"ת דהשיבנו מלמעלה יבא סיבת תשובה עילאה כו' אך הנה באמת ע\"י התשובה מן הריחוק דוקא רק כשהוא בעומקא דלבא במרירות עצומה שנוגעת עד יציאת הנפש כראב\"ד הנ\"ל הוא עיקר הכח ועוז שיהיה החזרת פב\"פ גם אם היה תחלה בבחי' אב\"א וזהו יתרון מעלת התשובה שיש בכחה להחזיר פב\"פ שהוא אהבת בכל מאדך הנ\"ל לפי שמרירות זו למעלה מהכיל בכלי המוח והלב בא מזה אה\"ר דבכל מאדך הנ\"ל וה\"ז ע\"ד משל אב ובנו או ב' אוהבים שמחזירים פנים זה מזה ומתרחקים מאוד שכאשר יתעורר הבן מרחוק וצועק בקול מר עד שנגע לנקודת נפשו על דבר הריחוק הזה עד שמואס בחייו כו' הנה אע\"פ שעומד האב מרחוק בבחי' אב\"א עמו מתעורר גם הוא להחזיר פניו אליו ונמצא סיבת קירוב פב\"פ הזה בא מצד סיבת הריחוק של הבן או האוהב ממה שצעק במרירות בעודו מרוחק דווק' שאם היה מקורב לא היה לבבו במרירו' כלל כו' וכפי אופן המרירות שהיא למעלה מהכיל בכלי כו' כך הוא התהוות אופן החזרת פנים בבחי' אה\"ר שלמעלה מן הכלי"],[2500660525,"שהוא אהבת בכל מאדך במשפיע ומקבל כו' ולפ\"ז יובן שהתשובה שגורמת יחוד דפב\"פ מאחר שיש בכחה לעשות חזרת פנים בפנים זה מוכרח שהיא למעלה גם מגופו של יחוד זה דפב\"פ כו' וא\"כ הרי בע\"ת שגדולי' מצד\"ג היינו גם מאהבת דבכל מאודך שבצדיקים גמורים בק\"ש כו' וד\"ל. וזהו שהזוהר אמר על בע\"ת דמשכי ליה לקב\"ה בחילא יתיר פי' משכי לי' לקב\"ה להיות בבחי' אהבה רבה דיחוד פב\"פ הנ\"ל בחילא יתיר ע\"י עומקא דלבא שלהם בעוצם המרירות עד יציאת הנפש שזהו למעלה גם מבכל מאדך ע\"כ נק' חילא יתיר כו' (ופי' חילא יתיר היינו בחי' יחידה שבנפש משא\"כ בכל מאדך אף שהיא בלי גבול היינו רק לגבי כוחות הנפש כמו הרצון והשכל כו' שנק' מקיף לגביהם אבל לא עצם פנימית הנפש שנק' יחידה שלא נק' מקיף לגבי כוחות הנפש כמ\"ש במ\"א בענין ל\"מ דצלם כו') ומ\"ש השיבנו כו' דמשמע שסיבת החזרת פב\"פ בא מלמעלה למטה דוקא ולא ע\"י התשובה שלמטה כמו גודל המרירות על הריחוק כנ\"ל הענין הוא דשניהם אמת דלעולם אין בכח להחזיר פב\"פ אלא מלמעלה גם ממקור השפע דמשפיע ומקבל והוא מבחי' הכתר מבחי' פנימיות שבו דוקא כי בחי' חיצוניות שבו כבר מלובש בחו\"ב וזו\"נ כידוע ובחי' פנימיות הכתר הוא בחי' כת\"ר שבכת\"ר שנק' בזוהר רעוא דכל רעוין (פי' מקור כל הרצונות ואין הכונה בחי' מקור של פנימיות הרצון לבד כנ\"ל בבחי' בכל נפשך שהוא רצון פשוט שלמעלה מן השכל לבד שא\"כ לא היה נקרא רעוא דכל רעוין שכולל להיות מקור של כל הרצונות גם לכל רצונות הפשוטים שלמעלה מן השכל ולא לרצון פשוט בפרט הוא מקור מהווה אלא הוא כללות המקור לכל הרצונות הפשוטי' ואח\"כ מסתעף ממנו דרך פרט להיות מקור לרצון פשוט בפרט כו' וזהו פי' רעוא דכל רעוין פי' מקור הרצון הכללי של כל הרצונות כו' והיינו ענין בעל הרצון שממנו נמשך רצון כללי לכללות כל הרצונות כו') ונמצא מובן דגם אהבת בכל מאדך שהוא בבחי' עצמות הנפש ממש שלמעלה מבחי' התפעלות רצון"],[2500660526,"פנימי ג\"כ עדיין אין מגיע רק בבחי' פרט של רצון הפשוט הכללי הנק' רעוא דכל רעוין כשנעשה מקור פרטי לאה\"ר זו דבכל מאדך בלי גבול כו' אבל לא בעצמות מהות רעוא דכל רעוין ממש (כמו בחי' גילוי רעוא דכל רעוין במנחה דשבת כמ\"ש ואני תפלתי כו' עת רצון עת פרטי מרצון העצמי הפשוט הזה כו') וגם עצמות דרעוא דכל רעוין הרי נק' בשם רצון רק שהוא רצון של כל הרצונות א\"כ הרי גם הוא בטל ונכלל בבעל הרצון עצמו ממש כו' (ונמצא סדר המדרגו' ברצון כך הוא א' רצון שבא מצד השכל והב' רצון שלמעלה מן השכל והוא בכל נפשך והג' התפעלות עצמות הנפש שלמעלה מבחי' רצון אבל הוא מקור הרצון ונק' בכל מאדך שמקבל דרך פרט מעצמות רעוא דכל רעוין כנ\"ל והד' בחי' עצמות דרעוא דכ\"ר בחי' מקור למקור הרצון עכ\"פ כו' וה\"ה בחי' בעל הרצון כשעלה ברצונו הפשוט ההיולי הכללי הנק' רעוא דכ\"ר כו' וד\"ל) וכמ\"כ ע\"י בע\"ת דמשכי בחילא יתיר כמו זה בכל עצמות הרצון ההיולי מקור כללי לכללות הרצונות מלמטה למעלה כענין מרירות העצומה על הריחוק שלהם כנ\"ל ושניהם אמת וד\"ל:\n(מט) <b>וזהו</b> שאמרו רז\"ל יפה שעה אחת בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב דפי' חיי העוה\"ב היינו בחי' מקור היו\"ד דחכמה שבו נברא העוה\"ב בחי' פנימיות בינה יובלא עילאה כו' והוא בחי' קוצו של יו\"ד בחי' הכתר וגם בחי' פנימיות הכת\"ר שנק' כל חיי העוה\"ב גם הוא כלא חשיבא לגבי כחה של תשובה שגורם בחי' החזרת יחוד פב\"פ דחו\"ב כו' מפני ששרשו מגיע בבעל הרצון עצמו שמשם נמשך מקור למקור כל רצון כו' וד\"ל. וכמ\"כ ע\"י מע\"ט שהן קיום המצות דגם שהמצות שרשם רק בחי' פנימיות רצון העליון שמתצמצם בחו\"ב כו' אבל אמיתית מקורם הראשון היינו בבעל הרצון עצמו כו' וד\"ל. והעושה המצוה דווקא הוא המעורר לבעל הרצון שלמעלה מן רצון העליון שבמצות וכמו במ\"ת שאמרו נעשה ואח\"כ ונשמע דזהו קבלת כל רצון העליון מצד שבכל עצמות נפשם שלמעלה גם מבחי' מקור לכל רצון קיבלו עליהם כל רצון"],[2500660527,"שישמעו והיינו נעשה כל רצון שיבא בהתגלו' בשמיעה אח\"כ שהוא רצונו המורכבים בחו\"ב וגם כל רצונות הפשוטים הפרטיות כו' ובזה נתעורר למעלה ג\"כ בחי' בעל הרצון מקור כל הרצונו' הפנימיות שבמצות וזהו שארז\"ל כאן כשישראל עושין רצונו של מקום פי' עושין רצונו בבחי' המקור של הרצונות כו' ומאחר שיש בכחם לעשות רצון במקור כל הרצונות שנק' רעוא דכל רעווין כנ\"ל בהכרח שזהו בבחי' בעל הרצון עצמו כו' וד\"ל. וזהו שאמרו לשון רצונו של מקום דוקא ולא רצונו של הקב\"ה וכה\"ג בהיות מבואר למעלה בפי' הוא מקומו של עולם ואין העולם מקומו דבחי' מקום הוא בחי' ממלא וסובב עד רום המעלות גם בראשית הארת הקו והחוט מעצמות א\"ס ממש וז\"ש הנה מקום אתי וזהו הוא מקומו של עולם אך הנה כדי שיהיה הוא ית' נק' מקומו של עולם בבחי' סובב וממלא מאחר שבאמת אין העולם מקומו כו' הוצרך להיות בחי' צמצום הרצון שיהיה רצון העצמות בהשתלשלות דסובב וממלא הנק' מקום והוא הנק' רצונו של מקום בכללות הכל מראש לסוף ולא רצון הבא דרך פרט הבא בהשתלשלות דקו וחוט כו' ולכך לא א' רצונו של הקב\"ה שהוא בחי' כתר דז\"א או בחי' כתר או\"א וא\"א וע\"י כו' (וגם אם פי' קדוש וברוך כו' הוא בחי' סובב וממלא כמ\"ש במ\"א מ\"מ הרי פי' רצונו של הקב\"ה הוא הרצון הבא מהקב\"ה בחי' סובב כו' אבל רצונו של מקום הוא הרצון להיות בחי' סובב כו' כנ\"ל ובאמת כמו כן יתפרש ברצונו של הקב\"ה כו' והאמת הוא בפי' רצונו של מקום כפשוטו מבחי' מקומו העצמי נמשך הרצון והכל א' וד\"ל) והיינו בחי' בעל הרצון עצמו שממנו נמשך רצון הפשוט הכללי בחי' רעוא דכ\"ר הנ\"ל שהוא הנק' רצונו ש\"מ דסובב וממלא בכלל דוקא כנ\"ל וד\"ל. והנה פי' עושין רצונו של מקום הנ\"ל היינו לעשות בבעל הרצון צמצו' זה דרצונו ש\"מ להיות לו רצון זה הכללי שזה הרצון הוא מקור הראשון דסובב וממלא כמ\"ש בריש הורמנא דמלכא גליף גליפו כו' דהיינו כשעלה ברצונו הפשוט הכללי שנקרא רעוא דכ\"ר ונקרא רצונו של מקום כנ\"ל והנה באמת כל בחי'"],[2500660528,"רצון אפי' בחי' מקור למקור הרצון בכללו' כמו רעוא דכ\"ר מאחר שיפול בו שם רצון עכ\"פ ה\"ז בחי' צמצום גדול לגבי בעל הרצון עצמו שמושלל לגמרי מכל בחי' רצון גם בכללות כו' שהרי עד\"מ באדם גם בחי' רצון פשוט הכללי שממנו נולדו ונמשכו כל הרצונות כו' ה\"ז בחי' צמצום לגבי עצמות הנפש כמו שהיא בעצמותה ממש שאינה רוצה בשום רצון כלל ואדרבה הרי מה שתתעורר הנפש בהתפעלות רצון גם בהתפעלות רצון פשוט להיות רוצה בכל הרצונות ה\"ז בחי' שינוי ותמורה כי לפעמי' יתפעל להיות רוצה ברצון ולפעמים לא ירצה בכל רצון אם בשינוי עתים או בשינוי אופנים לפי אופן ההתפעלות בעצמות הגורם הרצון הכללי הזה וידוע דכל בחי' התפעלות הוא בחי' שינוי ונקרא מורכב ולא פשוט דהיינו שבחי' העצמות ממש הנק' פשוט נעשה מורכב בדבר מה שאינו מבחי' העצמות כמו שמורכב ברצון שבו יש שינוי ותמורה כו' והתפעלות עצמה שברצון זה הוא בחי' הרכבה לגבי העצמות הפשוט הנקרא בעל הרצון כו' וכך ממש יובן למשכיל למעלה בבחי' אחדות הפשוטה בתכלית הפשיטות דעצמות א\"ס ב\"ה שבו לא יתכן ג' אלה שינוי והתפעלות והרכבה ושלשתן א' הוא דהשינוי בא מצד התפעלות עצמה שהוא שינוי והוא מפני שהתפעלות הוא בבחי' הרכבה כנ\"ל אבל בעצמות אור א\"ס הפשוט בתכלית מושלל מכל בחי' הרכבה לגמרי ולא יתכן בו בחי' התפעלות ושינוי רצון כו' מאחר שהוא פשוט בתכלית הפשיטות וכמ\"ש ולאו מכל אינון מדות כלל אפי' המקור של הרצון שנק' מדה עכ\"פ כי הרצון יש לו בחי' התפשטות בשיעור ומדה עד כאן הוא רוצה לא יותר וכן עד כאן רוצה ברצון לרצון וכה\"ג ולכך נק' מאמר קו המדה גם בכללות הכל כו' וז\"ש בזהר אפי' אור צח אור מצוחצח שהוא רעוא דכל רעוין כו' בחי' כת\"ר דכת\"ר בכלל אוכם הוא לגבי עילת העילות עצמו הפשוט בתכלית כנ\"ל דבחי' צמצום גדול הוא להיות מורכב גם בבחי' מקור למציא' רצון כו' משום שנאמר אני הוי\"ה לא שניתי כלל וכלל דהיינו בחי'"],[2500660529,"בעל הרצון עצמו שאין בו שינוי והתפעלות כלל בין קודם ההשתלשלות הנמשך ממקור הרצון כו' לאח\"כ ולכך אנו אומרים דרך בקשה יהי רצון מלפניך פי' יהי' בחי' צמצום לצמצם א\"ע להיו' מורכב ברצון כמו שצריך לצמצם מאד להיות בחי' אור החכמה כך בעל הרצון מצמצם א\"ע להיות מורכב בבחי' רצון כנ\"ל וזהו מלפניך בבחי' העצמות ממש שנקרא בעל הרצון יהיה צמצום הרצון הכללי כו' ומשם יומשך למט' דרך פרט בהשתלשלו' דקו עד בחי' כתר דמל' דעשיה שהוא מ\"ש כל אשר חפץ ה' עשה כו'.\n<b>(וזהו</b> ג\"כ פי' יהא שמי' רבא מברך כו' דשמו גי' רצון ושמו הגדול הוא בחי' רצון הפשוט הכללי מקור כל הרצונות הנקרא רעוא דכל רעוין הנ\"ל ושמו הגדול הזה יתברך ממקורו מבחי' בעל הרצון והיינו יהא שמי' רבא מברך כו' לעלם עד לעלמי עלמיא בסוף ההשתלשלות דקו כו' ג' עולמות דבי\"ע כידוע וד\"ל). ומעתה יובן ג\"כ ענין עושין רש\"מ מבחי' בעל הרצון נמשך רצון למקום בכלל כנ\"ל שזהו ע\"י קיום המצות שממשיכי' מבעל הרצון דוקא כנ\"ל ולכך א' רש\"מ דוקא כו' וזהו שאמרו ב' דברי' הללו תשובה ומע\"ט ובעה\"ז דוקא לפי שב' דברי' הללו גורמים להיו' החזרת פב\"פ שלמעלה מגופו של יחוד דפב\"פ כנ\"ל לפי שמעוררים בבעל הרצון עצמו דוקא שביכולתו להחזיר פב\"פ כנ\"ל וזהו שאמר תשובה ומע\"ט בעוה\"ז דוקא לפי שבעוה\"ז הוא בחי' הבירורים לאהפכא חשוכא לנהורא כו' מלמטה למעלה בבחי' אור חוזר וכל בחי' אור חוזר חוזר לקדמותו שזהו לבחי' קדמון לכל הקדומים שנק' בעל הרצון הפשוט כו' והוא למעלה מבחי' אור ישר שבאהבת בכל נפשך שאין ההארה רק בבחי' צמצום ממקור הרצון שנקרא רעוא דכ\"ר כו' ובע\"ת גדולים מצדיקי' גמורים גם מאהבת בכל מאדך שלהם לפי שע\"י התשובה גורם להיו' אהבת בכל מאדך שהוא פב\"פ כנ\"ל מטעם הנ\"ל וד\"ל. וכן ע\"י מע\"ט בעוה\"ז דוקא מטעם בחי' הבירורים כידוע וד\"ל. וזהו שארז\"ל על מה דרמו קראי אהדדי כתיב והיה מספר בנ\"י כו' וסיפא דקרא אשר לא"],[2500660530,"ימד ולא יספר ומשני ל\"ק כאן כשישראל עושין רש\"מ כו' אז לא יספר כו' פי' כשעושין רש\"מ שאז קשורים ודבוקים בעצמות בעל הרצון שמשם ממשיכים להיות לו רצון במקום בחי' סובב וממלא כנ\"ל ע\"י קיום המצות בקבלת העול לבד כמו שאמר נעשה ונשמע כו' כנ\"ל (וזהו הקים על מאה ברכות שהן ע\"ס שבכתר דכתר שיצאו מבחי' העלם עצמות בעל הרצון כו' וד\"ל) ומשום דנעוץ תחלתן בסוף מעשה שהוא בחי' דוד עול קבלת מ\"ש ע\"כ דוד דוקא הקים על כו' וכמ\"ש במ\"א וכתיב כי נר מצוה ותורה אור שע\"י נר מצוה שהוא בחי' עול מצות שנקרא מצות המלך נעשה תורה אור (שע\"י התורה ג\"כ יאיר אור הנעלם שבעצמות בעל הרצון כמשי\"ת בסמוך) ואז נאמר לא ימד ולא יספר לפי ששרשו בעצמות אא\"ס בעל הרצון שע\"ז א' לפני א' מה אתה סופר (ומ\"ש בר\"מ העשיר לא ירבה מעשר ע\"י הדעת שנקרא עשיר והד\"ל בחי' יסוד לא ימעיט כו' כל זה בע\"ס הגנוזות בעצמות אבל בעצמותו ממש לא מכל אלין מדות כלל אפי' בהעלם וז\"ש מה אתה סופר אפי' בהעלם כו') ונקרא יחיד קדמון לכל הקדומים שאין עוד מלבדו רק אחד פשוט בתכלית כו' אבל כשאין עושין רש\"מ בקיום המצות בקבלת ע\"מ (מלמטה למעלה בבחי' א\"ח כנ\"ל) אז כתיב והיה מספר שהן בחי' תרי\"ג ארחין כו' שבאין במספר ולא כמו שהן בשרשן בבעל הרצון שהוא למעלה מבחי' מספר לפני אחד כו' ואע\"פ שמקיימין המצות כך כשאין זה בקבלת עול כענין נעשה כו' לפי שקבלת עול למעלה מגופו של מעשה המצות מטעם הנ\"ל וזהו שכר מצוה מצוה עצמה שנעשית בקבלת עול כו' וד\"ל (ומבואר במ\"א והיה מספר כו' דהמספר יהי' בבחי' למעלה מן המספר כו' ולק\"מ מרישא לסיפא והיינו בחי' עליית המל' בחי' מספר קבלת עול לבד בבעל הרצון שלמעלה מן המספר כו' וזהו הקים על עול\"ה של תורה כו' משום דנעוץ תחלתן בסופן דוקא כו' וד\"ל). והנה כמו שמבואר למעלה בב' דברים תשובה ומע\"ט בעוה\"ז שעל ידם יוכל להיות בחי' החזרת פב\"פ כו' כך גם ע\"י"],[2500660531,"התורה יוכל להיות החזרת היחוד פב\"פ גם שהיה תחלה בבחי' אב\"א יותר מע\"י תשוב' ומע\"ט (והיינו ג' דברים תורה ועבודה וגמ\"ח תורה קו האמצעי ועבודה קו השמאל בחי' בירורים דא\"ח דע\"י תשובה וכן קרבנות להפוך נפש הבהמית מרע לטוב וזהו התפלה שבמקום קרבן כידוע וג\"ח שנקרא צדקה קו הימין שכוללת כל המצות כידוע ועל ג' אלה העולם עומד בחי' מקומו של עולם שנקרא רש\"מ מבעל הרצון כו') והטעם הוא מפני שהתורה נקרא ברית כמ\"ש אלה דברי הברית כו' וכתיב אשר כרת עמך ברית בחורב כו' כידוע וע\"י בחי' כריתת ברית שבתורה יוכל להיות בחי' חזרה דפב\"פ הנ\"ל יותר מע\"י תשובה ומע\"ט הנ\"ל. ולהבין דבר זה יש להקדים ענין ושרש הי\"ג מדות הרחמים אל רחום וחנון כו'. דהנה כתיב זכור רחמיך ה' וחסדיך כי מעולם המה. ויש להבין מהו מעולם כו' וגם מהו שצריך להזכירו לומר לו זכור רחמיך ה' כו' וכי איכא שכחה קמי קב\"ה כו' והלא אנו או' אין שכחה לפני כסא כבודך וכה\"ג. אך הנה ידוע ענין המאמר לאו דאית לך צדק ידיעא כו' עד ולאו מכל אינון מדות כלל שעצמות אא\"ס ב\"ה הוא פשוט בתכלית האחדות הפשיטות שלא יתכן בו לומר בחי' הרכבה כלל כנ\"ל אפי' בבחי' אורות הנקר' ספירות כי האורות שנאצלו הן בבחי' מהות ומציאות דבר מה בפרט כמו החכמה או החסד וכה\"ג ואיך יתכן בעצמות הפשוט ענין תואר מדות כמו חסדן ורחמן שהוא בא בבחי' התפעלות רחמים וחסד כו' ושינוי ותמורה כו' שזהו בחי' מורכב כנ\"ל וא\"א לומר שאא\"ס הפשוט יהיה נמשך בבחי' הרכבה גם בספירה ומדות וגם לא ברצון של כל הרצונות שנקרא כתר שבכת\"ר כנ\"ל ומכ\"ש בחכמה ומדות כו' (ומ\"ש חכים ולא בחכמה ידיעה שעכ\"פ נקרא חכים אלא שאינו בחכמה ידיעא בגילוי רק בבחי' ההעלם אין הכוונה בזה על בחי' ע\"ס הגנוזות בהעלם כו' דא\"כ קשה רישא לסיפא דמסיים ולאו מכל אינון מדות כלל דמשמע אפי' בהעלם אלא הכוונה על בחי' גילוי אור הנאצל דגם לאחר שנאצלו הרי איהו וחיוהי חד כו' שמיוחדים באצי' א\"כ גם"],[2500660532,"שנקרא חכים ה\"ז עדיין בבחי' העצמות ממש דלאו מכל אינון מדות כלל כו') אך מה שנק' חכים ומבין וכן חסדן ורחמן כו' אין זה מצד עצמותו הפשוט אלא מצד בחינת הצימצום שמצמצם את עצמו ונמשך ובא לכלל ספי' ומדה כמו רצון וחכמה וחסד וכה\"ג משום דחפץ חסד הוא כדי להטיב מטובו כמ\"ש בע\"ח ע\"כ עלה ברצון הפשוט כו' (וחפץ חסד זה איננו עדיין בבחי' מהות מדה כלל מאחר שהוא מקור להיות מחמתו אור הרצון הפשוט כו' אלא הוא אור עצמי הפשוט הנקרא טהירו עילאה כו' ובריש הורמנא כו' היינו קודם שעלה ברצונו כו' גליף גליפו חקיקה לחקיקה בחי' הארה דהארה באור חפץ חסד הפשוט הזה שבעצמות כמ\"ש באורך נראה אור ע\"י בחי' צמצום הנקרא מק\"פ כו' וד\"ל) וע\"כ גם שבתחלת ההשתלשלות היה חפץ חסד מצד עצמותו עצם הטוב כו' אבל אח\"כ צריך לעורר תמיד חסדו העצמי להיות משפיל ומצמצם א\"ע לבא לבחי' הרצון והחכמה ומדות גם בהעלם בעצמותו ומן ההעלם יבא לגילוי כו' וכמ\"ש בע\"ח דעכשיו תלוי במעשה התחתונים בהעלאת מ\"נ כו' והוא כמו שאנו מבקשים זכור רחמיך ה' וחסדיך כי מעולם המה פי' מעולם מעולם הא\"ס עצמו שהוא בחי' חסד העצמי שגורם להיות צמצום שמצמצם א\"ע לרצון וחכמה כו' בבחי' ע\"ס אורות וכלים כו' לאחזאה לאתנהגא בהון עלמין דבי\"ע כו' ומפני שבחי' החסד והרחמים שבעצמות אא\"ס ב\"ה הנק' רחמיך וחסדיך לנוכח הוא נבדל בערך לגמרי מכל ההשתלשלות דע\"ס כו' (כמ\"ש באורך נראה ע\"י צמצום כו' כנ\"ל) ע\"כ צריך לעוררו להזכירו על אותן החסדים העליונים הפשוטים בתכלית כו'. וז\"ש זכור רחמיך שיתעורר לזכור עליהם להיות חפץ חסד עוד הפעם לצמצם א\"ע ברצון וחכמה כו' כי מעולם הא\"ס המה ע\"כ אין להם ג\"כ הפסק ולא שכחה ח\"ו ולכך זכור רחמיך כו' (והפי' הב' זכור רחמיך וחסדיך הבאין בגילוי באצי' תזכור לעורר עצמך לצמצם א\"ע לבא לבחי' רצון וחסד ורחמים עד שתקרא בשם חכים וחסדן ורחמן כו' בבחי' אורות וכלים באצילות והיינו זכור רחמיך להיות זכרון עליהם ממקורם הראשון שבעצמות כו' כי"],[2500660533,"מעולם המה ששרשם בעצמות עולם הא\"ס כי חפץ חסד הוא כנ\"ל ע\"כ גם להם אין הפסק ושכחה מצד שרשם בעולם הא\"ס וזהו כמ\"ד זכות אבות לא תמה כו' ואעפ\"י שהאבות מרכבה רק לחג\"ת דאצילות אבל מצד שרשם בעולם הא\"ס עצמו הרי נאמר חסדי ה' כי לא תמנו כו' וז\"ש ושמר לך את הברית כו' וכמ\"ש במ\"א בפי' אשר נשבע לאבותיך מימי קדם כו') וזהו זכור רחמיך תחלה ואח\"כ וחסדיך וברחמיך הזכיר שם הוי' ולא בחסדיך כמ\"ש והמרחם כי לא תמו חסדיך ועל הרחמנו' א' הטוב שהוא החסד כי לא כלו רחמיך וזהו להיפוך שמהפך מבחי' רחמים לחסדים ומחסדים לרחמים מפני שהרחמים הוא בבחי' קו האמצעי שעולה עד פנימיות כתר שבכתר שהוא עד העצמות ממש (וז\"ש כי לא כלו רחמיך אך מ\"מ רחמים הללו מה שאין להן הפסק אלא בבחי' א\"ס עד שלא כלו רחמיך היינו שיזכור ה' לרחמיו הפשוטים וזכרון זה הוא ע\"י הטוב שבעצמו' כי חפץ חסד הוא כו' וכן להיפך שהחסד תלוי ברחמים וז\"ש והמרחם ע\"כ לא תמו חסדיך כו' כי שרש הרחמים בקו האמצעי בחי' יעקב שנאמר בו וגבה מאוד בבחי' א\"ס ממש ע\"כ לא תמו חסדיך למטה כמו זכות אבות ג\"כ לא תמו כו' וז\"ש זכור רחמיך תחלה ואח\"כ וחסדיך ולא נז' הויה בחסד מצד שרשו בחפץ חסד שלמעלה משם הויה משא\"כ הרחמים שהוא בת\"ת בחי' יעקב שזהו דוקא בשם הויה ולא באל דחסד כו' ומצד בחי' הויה בחי' ת\"ת דוקא הוא שעולה עד פנימיות הכתר כו' ע\"כ הזכיר הויה ברחמיך וכמ\"ש ליעקב אשר פדה את אברהם כו' וכמ\"ש במ\"א וד\"ל). וזהו שרש ענין הי\"ג מדה\"ר כמ\"ש ויקרא ה' ה' אל רחום וחנון כו' פי' ויקרא ה' ה' כו' הוא בחי' הקריאה וההמשכה מהעלם העצמות ששם ע\"ס גנוזות בהעלם כשלהבת הקשורה כו' שיבואו לידי גילוי בבחי' אצי' והיינו ב' הויו' העלם וגילוי ולמעלה יותר היינו בחי' עצמות הרצון הפשוט שנקרא רעוא דכל רעוין שבא בגילוי מהעלם עצמות בעל הרצון כו' עד בעצמותו ממש שיצמצם א\"ע לבא לכלל בחי' רצון גם לרעוא דכ\"ר כו' כנ\"ל והיינו ג\"כ ב' הוי' וכדי"],[2500660534,"שיתעורר לבחי' חפץ חסד העצמי מחדש שזהו מקור הכל כנ\"ל ע\"ז אמר ויעבור ה' על פניו כו' בעצמותו תחלה נתעורר לזכרון החסד העצמי כו' ויעבור זה בחי' צמצום גדול מעצמותו לזכור א\"ע על החסד כו' ואח\"כ ויקרא בבחי' העלם וגילוי להיות נק' אל רחום וחנון עד למטה באבי\"ע בפ\"מ כו' וד\"ל. וא\"כ הרי מובן עכ\"פ ששרש ענין הי\"ג מדה\"ר במ\"ש ויעבור כו' ויקרא הוא רק לעורר לבחי' העצמות הפשוט דוקא שיזכור חסדו הפשוט להיות רחום וחנון בגילוי מן ההעלם כו' אך ע\"י מה יהיה הסיבה לזכרון זה שמחמתו יעבור ה' וקורא מן ההעלם לגילוי הנה הוא רק ע\"י בחי' כריתת ברית שבתורה יותר מע\"י תשובה ומע\"ט כמשי\"ת בעזר\"ה כי מצד עצמו לאו מכל אינון מדות כלל וכנ\"ל בפי' זכור רחמיך כו' שצריך לעורר העצמות שיזכור על בחי' הרחמים וחסדים כו' שיבאו מעולם הא\"ס שבעצמות לידי גילוי כו' וד\"ל. אך הנה סיבת הזכירה הזאת הגם שבאה ג\"כ ע\"י תשובה מעומקא דלבא שמגיע בעצמות בעל הרצון להיות בבחי' רעוא דכל רעוין כו' עד שנמשך בגילוי רצון ולהקרות רחום וחנון כו' מ\"מ אין זה רק בחי' סיבה הגורמת לבד מפני שעולה בבחי' א\"ח על העצמות ובאתדל\"ת בבחי' עצמות הנפש מעורר למעלה בבחי' עצמות אבל אין ערך כלל ביניה' רק שמפני שזה עלה במחשב' ורצון הקדום תחלה כי נעוץ תחלתן בסופן כו' וכמו שאמרו דהתשובה קדמה לעולם כו' אך עיקר ומקור לזכירה זו שיזכור רחמיך כו' שבעולם הא\"ס כו' הוא רק ע\"י בחי' כריתת ברית שבתורה דוקא כנ\"ל וז\"ש ואשים דברי בפיך כו' לנטוע שמים וליסוד ארץ וכתיב אם לא בריתי כו' חוקות שמים וארץ כו' ועל מה אבדה הארץ על עזבם כו' הרי התורה עיקר קיום העולם בכלל בבחי' סובב וממלא כו' וא\"כ זהו עיקר ענין רצונו של מקום (ולכאורה למה אמר בקיום המצות שעושין רצונו כו') אך בחי' רש\"מ שהוא בחי' רעוא דכ\"ר הוא מקור המצות לבד כנ\"ל אבל בחי' מקור התורה הוא למעלה מזה (ע\"כ נמנו וגמרו דתלמוד גדול מפני שמביא לידי מעשה ות\"ת כנגד כולן"],[2500660535,"וכמשי\"ת). והנה תחלה יש להבין שרש ענין כריתות ברית מהו דהנה עד\"מ כריתת ברית שעושין שני אוהבים נאמנים שלוקחין איזה דבר אחד וכורתין אותו לשנים ועוברין שניהם יחד בתוך בין שני הגזרים האלה כמו כריתת ברית דאברהם דכתיב והוא עבר בין הגזרים כו'. וזה הענין מורה על עשיית ברית וחק קבוע ולא יעבור ולא יבטל עולמית גם אם יתרחקו זה מזה מאד או יביאו דברי נרגן להפריד בין הדביקים לא יועיל לבטל חק האהבה והאחוה הזאת מפני צד כריתת הברית באחדות זאת שלא תוכל להבטל מפני שא\"א לעבור על חק הברית הכרותה כבר ואפי' אם א' יפעל רעה לרעהו או יעשה מעשים מכוערים שראוי להתרחק ממנו מ\"מ חק כריתות הברית לא יניח לפעול לו רעה להשיב כגמולו או להתרחק ממנו גם אם מאד ראוי לריחוק מצד מעשיו אשר לא טובי' וכה\"ג במלכותא דארעא כשב' מלכים עושין כריתת ברית אע\"פ שיחטא א' לחבירו או יעשה א' רעה גדולה בעולם שראוי להעבירו ממלכותו לא יניח חק הברית הכרותה כו' כידוע אך מה שעושין מעשה זו לכרות דבר לשנים ולעבור בין הגזרים שאז דוקא נקרא כריתת ברית היינו מפני שזה המעשה מורה על היות שנעשו שניהם כגוף א' ממש כמו שגוף אחד כשנחלק לחצאין דאין לחצי זה חיות וקיום בלי חצי השני וכן חצי השני אין לו חיות בלעדי זולתו כי גוף אחד הוא וכל א' אין לו חיות עצמו לבד אלא בשיתוף חיות זולתו דוקא כו' ומפני שכשהן מחוברין אז הן גוף ומהות א' על כן גם כשמתחלקין אינן ב' דברים נפרדים כב' מהותי' אלא גם לאחר התחלקותן הן רק שני חצאין של מהות א' ואין צריך רק חיבור כשמתחברים נעשים מהות א' וזהו שלוקחין גוף דבר מה וכורתין אותו לשנים שב' חצאין הללו אינן ב' דברי' שלימים נפרדים אלא כל אחד נקרא חצי הגוף הא' לבד ומאמצעות שניהם יחד נקרא גוף ומהות א' כך כשעוברים בין ב' הגזרים האלה הנה עי\"ז עושין א\"ע כגוף ומהות א' שלא יהיה כ\"א מהות בפ\"ע בלא זולתו אלא כמו חצי גוף א' לבד וכך זולתו עד שאין לא' חיות בלא זולתו רק מאמצעות חיבור'"],[2500660536,"יחד הן גוף א' והיינו חק הברית באחדות ואחוה שלא יפרדו עולמית כמו שא\"א לגוף א' להפרד ולהחלק לחיות א' בלא חלק זולתו כו' ולכך גם אם יחטא איש לרעהו או יעשה רעה גדולה לא יפרדו בעבור זה מצד כריתת ברית שזהו כמו שאם היה ידו א' פועל רע בהכאה בידו הב' וכן רגל ברגל היתכן שיפרדו בעבור זה או שישיב כגמולו לחזור לו רעה בהכאה מאחר שגוף א' הוא וכל א' מורכב בחיות זולתו וכמ\"כ אם היד יחטא לעשות רעה להרוג וכה\"ג היתכן שיקח בידו הב' חרב ויקצץ אותה כו' וכך הוא כל ענין כריתת ברית שנעשי' כגוף א' ממש כנ\"ל וד\"ל. אך לפ\"ז לכאורה באה מעשה זו לסתור עיקר המכוון שהוא ענין עיקר האחדות והחיבור כגוף א' ומעשה זו שכורתין הגוף הא' לשנים הוא ענין המורה הפירוד וההתחלקות לב' היפך האחדות ולמה נקרא כריתת ברית שהכריתה הוא ההתחלקות והפירוד לשני' והברית הוא ההתחברות והאחדות דוקא וה\"ז ב' דברים הפכיים לכאורה ואיך יתכן לקרותו בשם כריתת ברית שהוא דבר והיפוכו אבל הענין הוא בהיות שבכאן הוא עשיית האחדות לב' גופי' שלמים נפרדים לעשותם כגוף א' ואיך יהיה מב' נפרדים דב' מהותי' גוף א' ממש עד שלא יהיה חיות לזה בלא זה כנ\"ל. והנה לזה עושין מעשה לעבור שניהם יחדיו בין ב' הגזרים שהוא גוף אחד שנכרת לשנים דאע\"פ שהן בפירוד הן כמו גוף א' ע\"כ בעבר' יחד שם אע\"פ שהן ב' הן נעשים א' מצד ב' חצאי הגזרים שעוברין ביניהם שמייחדים ומחברין אותם כי גם כל מה שבין ב' הגזרי' כדבר א' יחשב להיות שב' גזרים האלה גם בהיותם מפורדים כא' חשיבא ממש כנ\"ל ולכך נקרא כריתת ברית שהכריתה הוא העושה עיקר הברית שהוא עשיית האחדות להיות שכמו גוף א' נכרת לב' חלקים הרי עושין לב' חלקים הללו באחדות להקרות גוף א' כך כורתין ברית ב' גופים נפרדים לעשות בהם האחדות כגוף א' שנכרת כו' וד\"ל. אך עדיין אין זה טעם מספיק להקרו' שם הברית ע\"ש הכריתה דוקא שלפי הנ\"ל אין זה רק שהכריתה אינו נקרא פירוד אבל"],[2500660537,"לא שעל ידו נעשה עיקר האחדות במה שנכרת דוקא שלכאורה ודאי בעודו בשלימו' בלי כריתה היה בו בחי' האחדות יותר מכשנכרת ונתאחד אח\"כ כו'. אמנם הנה עיקר ענין הכריתה היינו שחולקים הדבר לשנים וכל א' נוטל חלק א' שנמצא ע\"י אותו הדבר שנכרת דוקא יש להן חיבור זע\"ז תמיד שכמו שיש בחלק זה מחיות חלק זולתו כך יש בזה מחלק חיות חבירו וכמו שאין לחלק זה שלימות עד שיתחבר בזולתו כך אין לאחד שלימות בלא זולתו ע\"כ בהכרח להתחבר יחד תמיד ע\"י ב' חצאים הללו שמחברים אותם במה שיש ביד כל אחד חלק א' וה\"ז כמו כל בחי' ממוצע שיש התחברות לב' נפרדים רחוקים על ידו מצד שיש לכל א' חיבור בזה הממוצע זה מצידו הא' וזה מצידו הב' ע\"כ ממילא יש להן חיבור ויחוד אבל הממוצע מפסיק ביניהם כמו שאוחז אדם ביד כלי מצד א' והב' אוחז ביד הכלי שמצידה הב' שאז הכלי מחבר' לבלתי יפרדו או דבר אחר כמו חבל הקשור בין ב' בנ\"א וכה\"ג והיינו הנקרא ממוצע שהוא דבר בפ\"ע ששניהם מתחברי' בו אך אין זה חיבור כגוף א' שאין מפסיק ביניהם וגם ב' חצאין של דבר שנכרת הרי מתחברים זע\"ז ממש בלי הפסק כלל ולזה מורה ההעברה יחדיו בין ב' הגזרים האלה שחיבור' עצמי הוא כגוף א' אע\"פ ששנים הן כמו ב' חצאי הגזרים כשמתחברין כו' וזהו דוקא ע\"י הכריתה מפני שכל א' אחוז וקשור בחלק הא' וב' החלקים ב' חצאי גוף א' הן אשר לזה אע\"פ שזהו כמו בחי' ממוצע אבל אינו מפסיק כלל ביניהם כשאר ממוצע אדרב' עי\"ז נעשים כגוף א' שהיחוד הוא עצמי בלי דבר מפסיק כלל וד\"ל. ולפי זה יובן היטב הטעם שנק' כריתת ברית שאין זה דבר והיפוכו אדרבא הכריתה דוק' לב' מה שכל א' מתקשר בחלק חצי א' עי\"ז נעשה החיבור והיחוד האמיתי להיות דבוקים יחד כמו ב' חצאי גוף א' כשמתחברים בלי יפרדו לעולם כו' וד\"ל:\n<b>והנה</b> הנמשל מכל ענין כריתת ברית למטה הנ\"ל יובן ג\"כ למעלה מעלה ברום המעלות כמו בכריתת ברית דאברהם שנאמר ויתן איש בתרו לקראת"],[2500660538,"רעהו כו' עד והנה תנור עשן כו' אשר עבר בין הגזרים כו' ביום ההוא כרת ה' את אברם ברית כו' שזה מורה כמו ב' גזרים הללו המה לגוף אחד בלי פירוד כלל כך יהיה לדורות יחוד קוב\"ה ושכינתיה כנ\"י כגוף א' כמו בבחי' יחוד איש ואשתו דכתיב והיו לבשר אחד אע\"פ שהן ב' גופי' נפרדים אך ע\"י כריתת ברית מתייחדים יחוד עצמי להיות כגוף בשר א' וכמו שא' אין האשה כורתת ברית אלא למי שעשאה כלי כו' והוא שאין לא' שלימות בלא זולתו כמו שא' אשתו כגופו דמיא ורוחא דשביק בגוה הוא עיקר הכריתת ברית מפני שעשאה כלי כו' עד שבאמצעות חיבורם יחד נקרא אדם שלם וא' בלא זולתו אינו אדם שלם אלא חצי גוף א' ע\"ד הנ\"ל בענין כריתת ברית שכורתין דבר לחצאין שאין לא' חיות בלא זולתו כו' וידוע דיחוד קב\"ה ושכינתיה אינו תמידי שלפעמים מתרחקים מאד בחי' ז\"א עולה למעלה מעלה ובחי' נוקבא יורדת למטה מטה כו' עכ\"ז לא יופר הברית שנכרת ביניהן ולא יבוטל האהבה לעולם וגם אם בהעלאה מלמטה גובר עונות וחטאים דכנ\"י עד שראויים לריחוק ולמאוס בהם לגמרי או שכפויי טובה הם להרהר אחר מדותיו וכה\"ג עכ\"ז נא' לא מאסתים כו' להפר בריתי אתם כו' מפני שהברי' הכרותה עושה אותם כגוף א' שלא יתכן בחי' פירוד להפריד ידו א' מחברתה כו' כנ\"ל והוא מצד כריתת ברית דאברהם הנ\"ל במה שעבר בין הגזרים דהיינו שהכריתה לשני' דוקא שכל א' נתן בתרו כו' עי\"ז יש להן חיבור ויחוד עצמי בלי דבר הפסק כלל ביניהם כנ\"ל ולא כשאר ממוצע שהוא מפסיק ביניה' אע\"פ שעל ידו מתחברי' וכמו שאמר משה אנכי עומד ואפסיק בין ה' וביניכם שהי' בחי' ממוצע מפסיק בין עצמות אא\"ס לכנ\"י אע\"פ שעל ידו מתחברי' והוא ע\"י גילוי וחיבור אא\"ס בחכמה כח מ\"ה שהוא מאיר בחי' ומדריגות משה ובבחינת החכמה דמשה מתקשרי' כנ\"י עי\"ז יש חיבור לאור א\"ס בכנ\"י אבל מ\"ש בזהר ישראל מתקשרין באורייתא ואורייתא בקב\"ה נמצא התורה היא בחי' ממוצע לחבר קב\"ה בכנ\"י אין התורה דבר מפסיק כלל בין קב\"ה לכנ\"י"],[2500660539,"אלא כמו שכורתין דבר לב' חלקי' וכל אחד מקושר בחלק אחד שעי\"ז מתחברי' חיבור עצמי בלי הפסק כלל כנ\"ל כך התורה שמקושרת בקב\"ה עצמות המאציל הוא בחי' אחרונ' שבעצמו' המאציל שאחוז וקשור בחכמה עילאה שבתורה בחי' פנימיות ח\"ס דא\"א שזהו כמשל חצי הא' כי חצי העליון דח\"ס דבוק למעלה בעצמות המאציל וחצי התחתון שהוא בחי' ז\"ת שבו אחוז וקשור בכנ\"י כי ישראל עלה במחשבה סתימאה כמ\"ש כי אתה אבינו וז\"ש ישראל מתקשראן באורייתא דהיינו בחי' ח\"ע וה\"ז כמו חיבור ב' חצאין חצי העליון עם חצי התחתון שנעשי' דבר א' כמבראשונה בלי דבר זר מפסיק ביניהן כלל כו' כנ\"ל וזהו עיקר ענין כריתת ברית שבתורה כמ\"ש אלה דברי הברית כו' וכן אשר כרת אתכ' ברית בחורב כו' וד\"ל אבל מה שאמ' משה אנכי עומד בין ה' וביניכ' הרי אמר עומד שהיה עומד ומפסיק כשאר ממוצע כמו שושבינא שעל ידו מתחברים חתן וכלה שהממוצע מפסיק ביניהם כך משה שושבינא דמלכא כו' וכמ\"ש למשה דבר אתה עמנו ואל ידבר עמנו אלקי' כו' נמצא שלא שמעו רק מפי משה (רק אנכי ולא יהיה לך מפי הגבורה שמענו) וכמ\"ש משה ידבר כו' ואע\"פ שבחי' משה הוא בחי' החכמה ג\"כ כנ\"ל וכשאו' ויאמר ה' אל משה לאמר לכנ\"י היינו בחי' גילוי אא\"ס בחכמה דמשה וממנו נמשך לכנ\"י וא\"כ לכאורה היינו הך דישראל מתקשרין באוריית' וכו' כנ\"ל. אך הנה יש הפרש בזה ויובן בהקדי' תחלה מ\"ש בע\"ח דבחי' הכתר הוא נקרא בחי' ממוצע בין עצמות המאציל לנאצלי' כי יש בו מבחי' האחרונה שבמאציל והוא שרש וראש לנאצלי' כו' וה\"ז כמו שאר ממוצע מפסיק הנ\"ל והוא מ\"ש משה אנכי עומד כו' בחי' מפסיק אנכי בחי' כתר דחכמה כמו שאמר ת\"ר אלף רגלי כו' העם אשר אנכי בקרבו כו' שהוא בחי' כתר הממוצע כו' אבל ע\"י התורה עצמה היא כמו חיבור ב' חצאין שנעשי' א' ממש ביחוד עצמי בלי דבר מפסיק כלל כנ\"ל. וטעם הדברי' הנה ידוע דהלכות שבתורה הן הן בחי' גילוי רצון העליון דוקא שבהן בא"],[2500660540,"רצון העליון הנעלם בהעל' אחר העלם בעצמות אור א\"ס הנקרא רעוא דכל רעוין וכה\"ג לידי בחי' גילוי דוקא עד למטה מטה בסוף עולם העשי' שהרי כשאומר זה כשר וזה פסול וכה\"ג ה\"ז מגלה ממש לבחי' רצון העליון כמו שהוא למעל' ממש בעצמות בעל הרצון דהיינו שעצמות בעל הרצון הביא לעצמות רצונו הקדו' הכללי הנעלם בעצמותו הנקרא רעוא דכל רעוין לבחי' גילוי כמו שהוא דוקא בלי שינוי לבוש ובלא שינוי המהות כלל וכלל אלא כמו שהוא ממש למעלה בעצמותו בא למטה כו' ולכך נקראו בשם הלכות דוקא כמ\"ש הליכות אלי כו' הליכות עולם לו פי' הלכו' כמו עד\"מ ההולך ממקום למקום שכל גופו ומהותו כמו שהוא ממש הולך ונמשך למקום שהלך לשם כו' כך כביכול למעלה כל בחי' עצמו' הרצון הפשוט הנקרא רעוא דכל רעוין כמו שהוא בעצמו' הולך ונמשך למטה בגילוי גמור בהלכות הנגלות לנו בתורה שבע\"פ באמרו זה כשר וזה פסול כו' ונמצא שא\"א לומר כלל שהתורה עצמה היא כשאר ממוצע שהוא מפסיק כו' כי הרי אין כאן שום הפסק בין העלם עצמות הרצון בין בחי' גילוי הרצון שבתורה מאחר שנק' בשם הילוך דוקא וז\"ש הליכות עולם לו הליכות אלי כו' וגם נקראו' דרכי ה' כידוע שנקרא דרך ואורח שהמלך בעצמו הולך בה כו' וד\"ל וזהו שאמר דוד בפקודיך אשיח' ואביטה אורחותיך פי' אורח ושביל שאור א\"ס ב\"ה בעצמו הולך ומתגל' בה כמו שהוא דוקא ע\"כ אמר אביטה אורחותיך שהן ההלכות שבתורה שנקרא אורח כנ\"ל וכמו עד\"מ הדרך הגשמי ההולך מעיר לעיר דרך המדבר אע\"פ שהדרך רחוקה ויש הפסק גדול בין עיר לעיר במדבר ושדה וכה\"ג מ\"מ אין הדרך נקרא בחי' ממוצע המפסיק רק שעל ידו מתחברים ב' העיירות הרחוקים זו מזו שהרי אין העיירו' עצמן מתחברין כלל רק שאנשי העיירות מתחברי' זע\"ז ע\"י הילוכם בדרך כידוע א\"כ אין זה הפסק כלל שהרי כשהולכים מעיר לעיר מתחברי' אנשי עיר זו בעיר אחרת חיבור גמור מפני שכל גופם ועצמם כמו שהן באו לעיר זו האחרת בלי דבר"],[2500660541,"מפסיק כלל רק שע\"י אמצעות הדרך באו לעיר וכמו כן השושבין שמביא את החתן לגבי הכלה או הכלה לגבי החתן וכשמביא' להתחבר הולך לו ומתחברים החתן והכלה יחוד גמור בלי הפסק כלל כו' וכך יש הרבה בחי' ממוצעי' שאינן נקראי' בחי' מפסיק כלל רק שמביאי' מן הריחוק אל הקירוב או מן ההעלם לגילוי אבל מביאין לגופו ומהותו של דבר שיתחבר בזולתו בלי הפסק ביניהם כלל וכך הן ההלכות שבתורה אף על פי שנקר' אורחות ה' ודרכי ה' אין דרך זה מפסיק מאחר שבה הולך אור העצמות ובא לבחי' גילוי גמור בכנ\"י בחי' יחוד גמור בלי הפסק כלל לכך אמר אביט' אורחותיך כלומ' אביטה באור עצמותך כשאתה הולך ובא ומתגל' באורחו' ההלכו' מהעל' עצמות' כאדם שרואה את המלך עצמו עובר בדרך כו' וד\"ל. וזהו עיקר ענין הכריתת ברית שבתורה כמו דבר א' שנכרתה לב' חצאין שע\"י שכל א' אחוז וקשור בחלק א' מתחברי' יחוד עצמי בלי הפסק דבר מה ביניהם כלל כנ\"ל (ולא כמו עד\"מ חבל ארוך שראשו האחד ביד אחד וסופה ביד השני שיש מפסיק ביניהם בריחוק מקום שהוא אורך החבל עצמו כו' משא\"כ משל הדרך גם שהוא ארוך אינו נקרא מפסיק כלל מטעם הנ\"ל וד\"ל). אך הנה מ\"ש בע\"ח דבחי' הכתר הוא בחי' ממוצע בין העצמות לנאצלים משום שיש בו מבחי' האחרונה שבמאציל וגם הוא שרש ומקור לנאצלים כנ\"ל הרי בחי' הכתר עצמו הוא נקרא בחי' ממוצע המפסיק רק שעל ידו יש חיבור למאציל עם הנאצלי' וכמו אנכי עומד ומפסיק כו' כמ\"ש דבר אתה עמנו דוקא כו' שאין גופו ומהותו של עצמות המאציל נגלה בנאצלים ביחוד גמור אלא בחי' האחרונ' שבו מתלבש בבחי' ג' ראשונות דכתר ומבחי' ז\"ת שבכתר מתלבש בנאצלי' כו' אבל בחי' ג\"ר שבו מובדל מן הנאצלים וכמ\"ש המתנשא מימות עולם כו' כידוע ומבואר במ\"א וד\"ל. והיינו בחי' משה גם שעל ידו ניתנה התורה והתורה עצמה אינה בחי' מפסיק כלל אבל בחי' משה עצמו הוא המפסיק מפני שאין ערוך כלל למקבל שהן כנ\"י לגבי המשפיע עצמו שהוא עצמות"],[2500660542,"אא\"ס ב\"ה ובכל מקום שאין ערך כלל בין המשפיע והמקבל בהכרח שיומשך השפע ע\"י בחי' ממוצע המפסיק דוקא כדי שיצומצם האור והשפע תחלה בממוצע זה וממנו נמשך למקבל (כמו יהושע שהיה ממוצע בין משה וישראל כידוע) וה\"ז כמו משל חבל ארוך ביותר שקצה העליון אחוז וקשור למעלה מעלה וקצהו התחתון אחוז וקשור למטה מטה ביותר שיש חיבור עי\"ז לעליון ותחתון אבל אריכות החבל עצמו מפסיק כו' וזהו שרש המצות שנקרא תר\"ך עמודי אור עד\"מ עמוד ארוך קצהו העליון למעלה מעלה ביותר וקצהו התחתון למטה ביותר כגג עם הרצפה וכה\"ג ואעפ\"כ על ידו יש חיבור לגג עם הרצפה כו' כידוע או כמו שושבין שאינו הולך לו בהביאו החתן לגבי הכלה אלא על ידו הולך כל אור השפע מזה לזה כמו ע\"י השליח וכמו דבר אתה עמנו וכה\"ג וד\"ל. והטעם הוא לפי שעצמות אא\"ס ב\"ה בעל הרצון נבדל בערך לגמרי גם מבחינת מקור לרצון הנקרא רעוא דכל רעוין כידוע וכדי שיומשך גם בבחי' מקור לרצון צריך להיות ע\"י בחי' הפסק וצמצום שזהו ע\"י בחי' ממוצע המפסיק דוקא שהוא בחי' הכתר עצמו שנקרא מפסיק כי בו נעלם בצמצום הארה האחרונה מבחי' העצמו' (בבחי' מסך מפסיק שנקרא מקום פנוי כו' ונקרא הארה דהארה כמ\"ש גליף גליפו כו') ואח\"כ יוכל להיות המשכה מבחי' הכתר לנאצלים שזהו בחי' הרצון העליון כשעלה ברצונו כו' וכך צריך להיות בחי' ממוצע מפסיק בין העלם הרצון שנק' רעוא דכל רעוין לגילוי הרצון כו' אבל לא שעצם העלם הרצון בא לידי גילוי וז\"ש אנכי עומד כו' שהוא בחי' משה שהיה שליח ממוצע בין העצמות לכנ\"י בענין השפעת התור' לישראל לפי שא\"א לכנ\"י לקבל התורה מעצמות אא\"ס כו' והיינו ויאמר ה' אל משה לאמר לכנ\"י כנ\"ל אבל לאחר שנית' התורה לישראל ע\"י משה יכולים הם להתייחד יחוד גמור בעצמות הרצון ממש הבא בגילוי בתורה בלי ממוצע מפסיק כלל כנ\"ל וזהו מצד שרש התקשרות התורה בעצמות ממש שנקרא אורח ודרך שהוא בעצמו"],[2500660543,"מתגלה בה לפי שנא' ואהיה אצלו אמון כו' בחי' שעשועי העצמיי שמצד עצמותו ממש וע\"כ אמר דהתורה קדמה לעולם כלו' קדמה לעולם הנאצל מרצונו הפשוט כו' וזהו למעלה ממקור המצות שהוא בבחי' רצון עכ\"פ כו'. אך מ\"מ כשצריך להשפיע וליתן התורה לישראל הוצרך להיות ע\"י בחי' ממוצע המפסיק מטעם הנ\"ל בכל משפיע ומקבל שאין ערך ביניהם כו' וז\"ש ובתורתו יהגה כו' לאחר שנק' תורתו שהוא אחר הנתינה שניתנה במתנה וכמ\"ש ממדבר מתנה כו' ואז נק' תורתו אומנתו כמשה עצמו כו' משא\"כ כשמקבל ע\"י ממוצע עדיין שנקרא תורת הוי\"ה כמ\"ש ויאמר ה' אל משה כו' ומ\"ש בזהר ישראל מתקשרין באורייתא היינו אחר שנתנה להם כו' ובזה מתורץ הקושי' הנ\"ל וד\"ל (ובכל דור יש בחי' משה עצמו כמו משה שפיר קאמרת שעל ידו נשפע וניתן תורה לישראל והוא עצמו מקבל שלא ע\"י הפסק גמור אבל מבחי' האחרונה שבעצמו' כו') ובזאת יש יתרון מעלה לתורה על המצות שלכך אמר תלמוד גדול כו' ות\"ת כנגד כולן כו'.\n<b>(וכן</b> גבי שבת נאמר ברית עולם ביני ובין בנ\"י אות היא לעולם כו' כי שרש השבת ותורה אחד הוא בבחי' פנימית ח\"ע שבעצמות וע\"כ נאמר בו שבת וינפש בעצמותו ממש כו' דמיקדשא וקיימא מוי\"ב כו' וכמ\"ש במ\"א ע\"כ גם השבת בחי' ממוצע המחבר בלי דבר מפסיק לעצמות א\"ס עם כנ\"י כמ\"ש ביני ובין בנ\"י אות היא לעולם כו' וד\"ל). וכך יובן בכל ענין כריתת ברית שנזכר בתורה ומ\"ש וראיתיה לזכור ברית עולם שהוא בחי' המל' משום דנעוץ תחלתן בסופן וסופן בתחלתן הנה זהו כמו משל חבל ארוך הנ\"ל וכמ\"ש יעקב חבל נחלתו כו' משא\"כ כריתת ברית שבתורה (וכן כריתת ברית לאברהם בשביל ירושת ארץ כנען וכמ\"ש והקימותי את בריתי לתת להם כו') ומ\"ש במ\"א ע\"פ לעברך בברית ה' אלקיך שזהו בבחי' הכתר שהוא בחי' ממוצע כו' היינו משום דכתר מל' איהו כ\"ע ונעוץ תחלתן בסופן כו' וזהו בחי' יעקב חבל כו' כשעושין רצונו של מקום בקיום המצוה שנא' בהן לא ימד ולא יספר כו' אבל בחי' ישראל"],[2500660544,"לי ראש שעלה במחשבה ורצון הקדום בבחי' עצמיות הוא במדריגה ושרש א' עם התורה וזהו בראשית בשביל ישראל שנק' ראשית כו' ומה שאמר בזהר ישראל קדישין אוריית' קדישא אבל אין קדוש כה' וכן ארז\"ל קדושי' תהיו יכול כמוני ת\"ל כי קדוש אני קדושתי למעלה מקדושתכם היינו מה שנק' קדוש מצד קיום מעשה המצות כשעושין רצונו של מקום (אך מ\"ש אורייתא קדישא ואין קדוש כה' היינו משום דגם שעצמותו מתגלה בה אבל הוא עצמו קדוש ומובדל גם מח\"ע דתורה כו') ונמצא תורה וישראל ושבת שרש א' להן ותשובה ומע\"ט למטה מהם כו' ולכך אומר שמע ישראל שבו תלוי היחוד העצמי דה' אחד כו' וד\"ל. ובכל זה הרי מובן ג\"כ בענין זכור רחמיך ה' שהוא ג\"כ שרש י\"ג מדה\"ר ויעבור ה' ויקרא ה' כו' שזהו ע\"י התורה יותר מע\"י תשובה ומע\"ט לפי שבחי' העצמות דהוי\"ה ממש נתגלה כנ\"ל. ומעתה יובן ג\"כ בענין החזרת פנים בפנים הנ\"ל שזהו ג\"כ ע\"י תורה יותר מע\"י תשובה ומע\"ט מטעם הנ\"ל וד\"ל. אך הנה יש להבין בתוס' ביאור בענין החזרת היחוד דפב\"פ שגדול יותר מגופו של יחוד כנ\"ל. דהנה באמת יש להפליא בשרש ענין יחוד דפב\"פ האיך יוכל להיות מצד עצמות שהרי ידוע שענין יחוד פב\"פ דקוב\"ה וכנ\"י א\"א להיות כ\"א ע\"י אתדל\"ת שמעורר אתדל\"ע באהבה כמים הפני' כו' וכמו ואל אישך תשוקתך בבחי' העלא' מ\"נ שמזה מתעורר אהבה ותשוקה למעלה מן המשפיע אל המקבל בבחי' המשכת מ\"ד (ויש בזה ב' מדריגות הא' מ\"נ ומ\"ד לעורר את היחוד והב' גופו של מ\"נ ומ\"ד שבשעת היחוד וזווג עצמו כידוע בענין המצות שאומר לשם יחוד כו' וכמ\"ש במ\"א) ולכאורה איך ביכולת אהבה של המקבלים שהן בבחי' גבול כו' כי הן נבראים יש מאין לעורר אור אהבה עליונה האלקית שבבחי' אצי' שהוא בבחי' א\"ס משום דאיהו וחיוהי חד כו' כידוע שאין ערוך כלל וכלל בין נברא עם הבורא כו' וא\"א לומר כלל שבאתדל\"ת דבי\"ע יגרום אתדל\"ע שבאצי' מאחר שאין ביניהם השתוות ערך כלל וכלל (שזה שיוכל לפעול התעוררות מוכרח שיש"],[2500660545,"להם השתוות ערך מסוג א' כמו ב' בנ\"א אבל אא\"ל שהחי יעורר את המדבר ומכ\"ש הדומם והצומח שאינם מערך אדם כו' וכמ\"ש במ\"א) והנה בע\"ח מבואר שהנשמות מעלין מ\"נ אל המלכות שהוא בחי' כח הפועל בנפעל מאין ליש ע\"י שהם מתבטלים מיש לאין שבזה יש שייכות לומר לכאורה שאתדל\"ת יעורר אתדל\"ע והמל' מעלה מ\"ן לגבי ז\"א כו' כידוע אך גם זה לא מובן דאיך נברא בע\"ג מעורר לבוראו שהוא בלתי בע\"ג מאחר שנברא יש מאין בדילוג הערך ע\"י בחי' צמצום הארה דהארה שנק' מסך כו' ולא דרך עילה ועלול שא\"א לומר רק שיפעול העלול התעוררות בעילה שלו כתלמיד לרבו וכה\"ג מפני שיש ערך קצת ביניהם כו' משא\"כ מאין ליש שאין ערך ביניהם כלל כידוע ומבואר במ\"א א\"כ גם בבחי' ביטול היש לאין שלהם אי אפשר שיוכלו לעורר ההמשכה מאין ליש כו' (ומ\"ש בזהר בכמה דוכתי שהמלאכים ונשמות מעוררים לבחי' המל' להיות בנין מחדש בבחי' פרצוף כו' כמ\"ש גבורי כח עושי דברו כו' ולהיפך כאשר אין העלאת מ\"נ לטוב אלא להיפך נעשית בבחי' קטנות וכמ\"ש בזהר האי ע\"ת או סלקא או נחת' כו' בחי' פגימת הלבנה ומילוי הלבנה כו' הנה זה גופא יש להבין איך יתכן שיהיה בחי' שינוי דקטנות וגדלות במל' מצד מעשה התחתונים בחי' בע\"ג שאין ערך כלל לנברא עם הבור' כנ\"ל וד\"ל):\n(נ) <b>אך</b> הנה כמו שיש להפלי' איך נעשה אתדל\"ע מצד אתדל\"ת כנ\"ל יותר יש להפליא מהיכן נמצא הכח בתחתוני' בע\"ג בבחי' נפרד להיות בהם בחי' אתדל\"ת בחי' ביטול היש לאין כו' שזהו לכאורה היפך טבע הבריאה שנברא לבחי' יש ונפרד דוקא כמו כל צבא השמים שהן בבחי' יש נפרד לעצמם מאין נמצא בהם בחי' הביטול במציאות בהשתחוואה כמ\"ש לך משתחווים וכן כל הברואים אומרים שירה כך עד רום המעלות שבג' עולמות בי\"ע עד נשמות שבג\"ע העליון דכתיב והיה מדי חודש בחדשו כו' יבא כל בשר להשתחוות כו' וגם בנשמות ישראל למטה גם שמלובשים בגופי' חומרי' מאד ומשוקעים בטומאות הגסות"],[2500660546,"דרוח הבהמה בחטאים ועונות מלבד עול הגלות בשיעבוד פרנסה בכל לב ונפש וכן בכל תאות היתר שמטמטם הלב כו' עכ\"ז נמצא בהם תמיד בחי' זאת דהתעוררות תשובה מעומקא דלבא בכל לב ונפש לשוב מן החטא לגמרי ולהיות מרי נפש ולצעוק אל ה' בתשובה בכל לב לשוב אל ה' לעבודתו האמיתית כמו בעי\"ת שאפילו קל שבקלים חוזר בתשובה ובוכה על נפשו שנתרחק בעונותיו וכה\"ג בשאר ימות השנה הרבה מתעוררים לפרקים לבלתי ידח כו' וזהו פלא גדול לכאורה שזהו כמו היפך הטבע ממש. אך הנה באמת אין התעוררות זאת מצד עצמם אלא מלמעלה נמשך עליהם רוח התעוררות זו כמ\"ש עד יערה עלינו רוח ממרום והוא ענין בת קול שמכרזת בכל יום לעורר לנשמות שנטמאו באיסור או בהיתר לומר שובו בנים שובבים כו' ומזה הכרוז הרבה מתעוררים בכל יום ויום ממש כידוע והיינו כמ\"ש השיבנו ה' אליך שתשובה זאת מאת ה' היא שהוא המשיב לכנ\"י בתשובה בהתעוררות זאת שמעוררים בכל יום כו' ונמצא שגם בחי' אתדל\"ת דתשובה אינה מצד עצמם אלא מלמעלה בא כח ועוז המעורר אותם (וכמשארז\"ל הבא לטהר מסייעין אותו כו') וכך הוא ג\"כ בכל בחי' העלאת מ\"נ דבי\"ע במלאכים וכל צבא השמים עד רום המעלות כנ\"ל הכל מאת ה' הוא שבא כח המעוררם בהתעוררות זאת ונותן בהן כח זה הביטול במציאות ואם לאו לא היה בהן בחי' ביטול זה כלל מאחר שהן בחי' יש נפרד כו' וראיה לזה ממה שמצינו בזוהר שבכל חצות לילה יש כרוז שמכריז לעורר הנשמות כו' והוא ענין הנותן לשכוי בינה בטש בגדפוהי דתרנגולא כו' ואו' הקיצו ורננו שוכני עפר כו' סתימין עיינין אטימין אודנין כו' ע\"ש וכך הוא עד רום המעלות גם בנשמות שבג\"ע העליון ובכלל הנה כללות בחי' העלאת מ\"נ דמלכות מצד הנבראים ע\"ז נאמר תנו עוז לאלקים שיוכל להעלות מ\"נ שנק' כח ועוז המעלה מ\"נ ואז נא' אלקים אל דמי לך קארי תדיר כו' וד\"ל. וכמ\"כ יובן שכמו שכח אתדל\"ת באה מלמעלה דוקא כנ\"ל כך כח של אתדל\"ע"],[2500660547,"שיהיה מתעורר מאתדל\"ת אע\"פ שאין ערוך ביניהם כלל וכלל ג\"כ בא מלמעלה מעלה מן המשפיע שמשם נמשך לו רצון וכח להיות מתעורר ומתפעל מאתדל\"ת הנק' בחי' מ\"ד עד שיבא לכלל יחוד פב\"פ שזהו מ\"ש יאר ה' פניו אליך כו' ונמצא שבין במשפיע ובין במקבל מה שהמשפיע בא לכלל החזרת פנים אל המקבל להתייחד במקבל בבחי' הפנימית שבו וכן מה שהמקבל יוכל להעלות מ\"נ מבחי' פנימיות שבו וחוזר פנים שלו אל המשפיע אע\"פ שהיה המשפיע והמקבל תחלה מרחוק מאד בבחי' אב\"א כו' הנה כל זה אינו בא מצד עצמות כח המשפיע והמקבל אלא דוקא מלמעלה נמשך כח החזרת פב\"פ דמשפיע ומקבל לעוררם בבחי' אתדל\"ת ואתדל\"ע בחי' מ\"נ ומ\"ד והיינו פי' עוזר ומושיע כו' שעוזר למשפיע ומקבל לבא לבחי' יחוד פב\"פ כו' וד\"ל.\n<b>(וזהו</b> ע\"פ מאמר קו המדה שבכת' באיזה אופן ובאיזה זמן ובאיז' מדה ושיעור כמה יהי' העלא' מ\"נ וכמה יהיה המשכת מ\"ד כמו אלה מועדי הוי' בג' רגלים דוקא אז זמן יחוד פב\"פ דכתיב יראה כל זכורך את פני הויה כו' וכה\"ג וד\"ל). והנה שרש ההמשכה של הכח הזה למשפיע ומקבל הוא נמשך מבחי' הפנימי' של הכתר דוקא שנקרא כת\"ר שבכת\"ר והוא בחי' רעוא דכ\"ר הנ\"ל מקור כל הרצונות שמשם נמשך בחי' רצון למשפיע שירצה להתעורר ולהתפעל באתעדל\"ע להיות מאיר פניו אל המקבל כמו יאר ה' פניו וכה\"ג ואם לא הארת רעוא דכל רעוין בז\"א לעורר לו רצון בהתעוררות זו לא היה מתעורר כלל מצד העלאת מ\"נ דכנ\"י מאחר שאין ערוך כלל ביניהם כנ\"ל וגם מה שיכולים כנ\"י להתעורר באתדל\"ת להחזיר פניהם אל ה' בתשובה שלימה אע\"פ שהיו עומדים בבחי' עורף ואחוריים תחלה כו' גם זה נמשך להם כח ועוז מבחי' רעוא דכל רעוין הנ\"ל שממשיך להם רצון שלו להיות להם התעוררות זאת ולכך נאמר עד יערה עלינו רוח ממרום דוק' כמו יעקב משמש במרום כו' (ומ\"ש בת קול מכרזת בחי' מל' משום שיש כח המעלה מ\"נ גם מכל משפיע אל המקבל מצד רוחא דשביק בגוה כו' וכן מז\"א למל' כו' אך ע\"ז"],[2500660548,"נאמר אם יגאלך טוב כו' וא\"ל וגאלתיך אנכי מבחי' הכתר שבכתר מי שאנכי כו') וזהו השיבנו ה' אליך מצד הארת רעוא דכ\"ר שנשוב בהתעוררות זו אליך ואז ונשובה בבחי' פנים ממילא כי תאיר ג\"כ פני הויה אלינו להתייחד פב\"פ כו' וא\"כ פי' השיבנו היינו שלא להיות בבחי' אחוריים והפנים בעניני עוה\"ז אלא השיבנו לבחי' פנים שיהי' בהתעוררות אמיתי' כנ\"ל ואז ונשובה להיות בבחי' פב\"פ כי יאר הויה פניו אלינו ממילא גם הוא ע\"י הארת רצון דרעוא דכל רעוין וז\"ש ואני תפלתי לך שהוא יחוד דזו\"ן פב\"פ דוקא בעת רצון העליון לזה היחוד מרעוא דכ\"ר כו' וכמ\"ש בזהר ע\"פ ואל יבא בכל עת כו'. וכמו אלה מועדי הויה בג' רגלים ושבת או בשחרית דכל יום כו' וז\"ש ששים ושמחים לעשות רצון קונם בחי' רצון דרעוא דכ\"ר והוא חק וזמן נתן להם שלא ישנו את תפקידם זמן יחודם כמו בקירוב השמש והירח בזמן ידוע כו' וכמ\"ש במ\"א. אך מה שיש כח גדול כזה בבחי' הכתר להחזיר למשפיע ולמקבל פב\"פ גם הוא מקבל מלמעלה הימנו דוקא והוא מבעל הרצון שהוא בחי' העצמות דא\"ס ממש וכידוע שבכל יחוד יש הארה וכח ליחודם מעצמות אא\"ס כו' והוא ע\"י שבחי' הכתר הנ\"ל הוא בחינת ממוצע בין עצמות המאציל לנאצלים וזהו ע\"י תשובה ומעשים טובים כנ\"ל שנקרא עושין רצונו של מקום כו' ועל ידי תורה ההמשכה באה מן ההעלם לגילוי כמו שהוא בלא דבר מפסיק וע\"כ הוא הגורם יותר בחי' החזרת פנים בפנים כנ\"ל וזהו עיקר ענין כריתת ברית שעל ידו יומשך רצון מרעוא דכל רעוין תמיד להיות חזרת פנים בפנים בקודשא ב\"ה וכנסת ישראל כו' (וזהו שאמר מניחין חיי עולם שהוא מקור לחזר' יחוד דפב\"פ שבתפלה שנקרא חיי שעה כו') ונמצא שע\"י ג' דברים הללו תורה ותשובה ומע\"ט נמשך רצון מרעוא דכ\"ר להיות החזרת פב\"פ בכל משפיע ומקבל עד רום מעלות כו' וד\"ל:\n(נא) <b>ואחר</b> כל הנ\"ל יובן היטב תירוץ של הה\"מ ז\"ל על קושיא הידועה הנ\"ל במה דרמו קראי אהדדי כתיב ואספת דגניך וכתיב ועמדו זרים כו' ומשני"],[2500660549,"כשישראל אין עושין כו' ואספת כו' דהא נא' בכל נפשכם והתירוץ הוא דפ' ראשונה נאמר ובכל מאדך ובפ' שניה לא נזכר בכל מאדך ע\"כ אין עושין רצונו ש\"מ וזה פלא לכאורה דבשביל זה יקראו אין עושין רש\"מ אע\"פ שיש להן מס\"נ גמור דבכל נפשכם כנ\"ל. אך הנה עפ\"י כל הנ\"ל יובן תירוץ זה היטב בהיות מבואר למעלה דבחי' רעוא דכל רעוין נק' רצונו ש\"מ שבכללות להיות לו רצון לרצון של מקום דסובב כו' ופי' עושין רצונו זה היינו לעשות לבחי' רצון הכללי שנק' רעוא דכל רעוין שיהיה נמשך מעצמות בעל הרצון אשר אח\"כ יוכל גם הוא להמשיך רצון במקום דסובב כו'. והנה מבואר למעלה ג\"כ דסיבת כל החזרת פב\"פ א\"א שיבא מצד עצמו ולא מצד אוי\"ר דבכל לבבך ובכל נפשך כו' מאחר שאין ערוך ביניהם כלל כו' אלא דוקא ע\"י ג' דברים הללו תורה ותשובה ומע\"ט כו' לפי שע\"י מע\"ט שעושין רצונו ש\"מ נמשך מבעל הרצון לרעוא דכ\"ר להמשיך רצון בחזרה דפב\"פ כנ\"ל שבכח רעוא דכ\"ר דוקא להחזיר פב\"פ במשפיע ומקבל וכן ע\"י תשובה שגורמת אהבת בכל מאדך דצדיקים גמורים בק\"ש כנ\"ל באריכות. ופי' מאד הוא בלי גבול שבעצם הרצון דרעוא כו' משא\"כ בכל נפשך שאינו רק האר' מצומצמ' ממקור הרצון דרעוא דכ\"ר כו' כנ\"ל באורך ומכ\"ש ע\"י מצות ת\"ת והיו הדברים כו' ודברת בם שהן ההלכות שנגלה עצמות הרצון דרעוא כו' כמו שהוא בעצמו' בעל הרצון ממש כנ\"ל באריכו' בפי' אביטה אורחותיך וכן מי שתורתו אומנתו כרשב\"י שזהו מבחי' משה כו' כנ\"ל. ומעתה יתורץ היטב דגם שנאמר בכל נפשכם בפ' שניה לא נקרא עושין רש\"מ אלא אין עושין רצונו שלא נמשך מבחי' עצמות בעל הרצון לרעוא דכ\"ר שנקרא רש\"מ בכלל וע\"כ אז נאמר ואספת כו' שהוא בחי' הבירורים לעבוד בעצמו בבחי' העלאת מ\"נ לעורר המשכת מ\"ד רק לפי אופן עבודתם לבד כנ\"ל בענין בכל נפשך כו' וז\"ש ולעבדו בכל לבבכם ובכל נפשכם (ובפ' הא' א' ואהבת את כו' בכל נפשך אהבה לבד שזהו כמ\"ש ריב\"ק שבפ' הא' מקבל עליו עול מ\"ש ובפרשה"],[2500660550,"שניה עול מצות שנק' עבודה כו') אבל כשעושין רש\"מ לעורר לעצמות רעוא דכל רעוין לעשות יחוד דפב\"פ כנ\"ל ע\"י ג' דברים דתורה ותשובה ומע\"ט אז נאמר ועמדו זרים כו' שהרי אמרו הרבה עשו כרשב\"י כו' שא' אפשר אדם חורש כו' אלא בזמן שישראל עושין רש\"מ מלאכתן נעשית ע\"י אחרים כמ\"ש ועמדו זרים כו' והיינו מי שתורתו אומנתו כנ\"ל והיינו מטעם הנ\"ל בשרש בחי' התורה שמתקשרת בעצמות אא\"ס ממש להביא מבחי' העלם עצמותו כמו שהוא לגילוי ולכך נקרא דרך ואורח כנ\"ל באריכות וכן ע\"י מע\"ט שנקרא עושין רצונו כו' ודוק' ע\"י אהבת בכל מאדך שבפ' הא' להיותה בבחי' בלי גבול וזהו ע\"י קבלת עול שבמצות דוקא ולא מצד המצות עצמן כנ\"ל באריכות אשר אין זה בבחי' אהבה דבכל נפשך כו' וכן ע\"י תשובה דבע\"ת דמשכי ליה לקב\"ה בחילא יתיר שגורמים אהבת בכל מאדך דצדיקים גמורי' כנ\"ל באריכות וא\"כ מפני שלא נזכר בכל מאדכם בפ' שניה נקרא אין עושין רש\"מ ואז ואספת כו' ובפ' הא' שנא' בכל מאודך ונקרא תורתו אומנתו כו' שמלאכתן נעשית ע\"י אחרים להיותו למעלה מבחי' הבירורים כו' וד\"ל:\n(נב) <b>וגם</b> הנה אחר כל הנ\"ל יובן בתוס' ביאור ענין ירידת הנשמה בעוה\"ז שירידה זאת לצורך עליי' היא כנ\"ל בהיות מבואר למעלה בשרש ישראל שעלה במחשבה עילאה סתימאה שהוא בחי' ח\"ע הפשוטה שבעצמות המאציל שלמעלה מבחי' אותיות כו' אבל אין זה ערך לגבי הרצון הפשוט שנקרא רעוא דכ\"ר שלמעלה גם מן ח\"ע הפשוטה כי בכל מקום עד רום המעלות בחי' הכתר למעלה נבדל בערך מבחי' החכמה כו' (כמ\"ש והבדילה הפרכת בין קדש דח\"ע לקה\"ק דכתר כו' וע\"י תשובה ומע\"ט בעוה\"ז תתעלה נפש ישראל זה למעלה משרשו בח\"ע והוא שנכלל ועולה מבחי' רעוא דכ\"ר וזהו ירידה בעוה\"ז לצורך עליי') ולפי' הב' הנ\"ל במחשבה שהוא הרצון הפשוט דרעוא דכ\"ר עליה זו למעלה גם מרעוא דכ\"ר והוא בבעל הרצון עצמו כנ\"ל וזהו התורה שלמעלה מתשובה ומע\"ט כנ\"ל"],[2500660551,"דישראל ותורה שרש א' להן בעצמו' בעל הרצון הקדום (ואמר במדרש ז' דברים קדמו לעולם תורה ותשובה כו' מחשבתן של ישראל קדמה לכולן כמו כן א' במי נמלך ברצון הפשוט בנשמותיהן כו' וכן בזהר א' זכאין ישראל דקב\"ה אתרעי בהון כו' וכנ\"ל בענין אורייתא קדישא וישראל קדישין כו' ע\"כ א' ג' קשרין הן ישראל מתקשרין באורייתא כו' וזהו בשביל ישראל שנקראו ראשית ובתורה נאמר ה' קנני ראשית דרכו ברצון הפשוט כו' וד\"ל) וזהו ענין ד' הבדלות המבדיל בין קודש לחול היינו מ\"ש והבדילה הפרכת בחי' צמצום דמק\"פ שמבעל הרצון להיות רצונו ש\"מ שהוא בחי' רעוא דכ\"ר בכלל ואחר כך ג' הבדלות א' בין אור לחושך שזהו בחי' אור דתורה כו' והב' בין ישראל לעמי' שזהו שרש ישראל לי ראש שנקרא ראשית כמו התורה ואח\"כ הבדלה ג' בין יום הז' כו' וג' אלה שרש אחד להם כנ\"ל דתורה וישראל ושבת שרש א' להם וזהו הבוח' בתור' הבוחר בעמו ישראל כו' וכמ\"ש במ\"א וד\"ל:\n(נג) <b>וזהו</b> והיה עקב תשמעון את המשפטים האלה. דהנה פי' משפטים תרגום משפט הלכתא וקאי בהלכות שבתורה שבע\"פ שנקרא הלכתא כידוע ופי' תשמעון לשון אסיפה וקבוץ כמו וישמע שאול כו' דהיינו לקבץ ולאסוף כל בחי' פיזור ההלכות שבתורה שנתפזרו בזמן הגלות שהתורה חוגרת שק כו' והענין הוא דכיון שאמר ג' קשרין ישראל מתקשרין באורייתא ואורייתא בקב\"ה א\"כ כאשר ישראל בגלות בע' שרים וישראל מתקשרין באורייתא גם התורה היא בגלות כו' ואוריית' מתקשרא בקב\"ה ע\"כ אמרו גלו לאדום שכינ' עמהם שהשכינה בגלות ג\"כ עם ישראל ותורה דאורייתא וקב\"ה כולא חד כו' וביאור הדברי' הנה ענין גלות של ישראל באוה\"ע הוא כמו בכל פרט בניצוץ האלקי הנקרא ישראל שנתפזרו כל פרטי חלקיה בפיזור רצונות הזרות והנכריות של נפש הבהמית שמלובשת בה ונעשי' לה בחי' לבושים צואים ביותר כידוע וצריך תחלה להיו' בחי' קיבוץ ואסיפה מכל פיזור רצונות הזרות שהנפש הבהמית קשורה בהן ע\"י תשובה"],[2500660552,"מעומקא דלבא שעי\"ז נתקבצו כל חלקי נצוצות דנפש האלקי ועולין מעולם הפירוד לעולם היחוד והוא הנקרא קיבוץ גליות בכל ניצוץ בפרט וז\"ש אם יהיה נדחך בקצה השמים משם יקבצך נדחך ל' יחיד כו' וכמ\"ש במ\"א וכך הוא ענין קיבוץ גליות בכללות נ\"י שכל מה שנתפזרו כל ניצוצות הקדושים שבכנ\"י בבחי' גלות בע' שרים בהסתר הלבושים צואים שמשועבדים בהם כו' יתקבצו ויעלו ליכלל באחד כו' וזה שאמר נדחי ישראל יכנס וכן אנו אומרי' מקבץ נדחי עמו ישראל וכמארז\"ל אם עושין תשובה נגאלין שבלתי תשובה שהוא הקיבוץ והאסיפה של הניצוצות הרי הן מפוזרים בע' שרים כו' בעולם הפירוד והוא עצמו סיבת הגאולה שנקרא קיבוץ גליות כו' וכך יובן בגלות השכינה דגלו לאדום שכינה עמהם וכך בכל פרט הפיזור של ישראל בע' שרים הרי בחי' פיזור דנדחי ישראל תחת ממשלת ע' שרים הוא עצמו ענין פיזור גלות השכינה (כמ\"ש מלך אלקים על גוים) כמ\"ש עת אשר שלט האדם באדם לרע לו כדי שיוברר ממנו הטוב כו' כי כל גלות הוא בחי' בירור כידוע ובחי' הקיבוץ גליות שבגלות השכינה ג\"כ עד קיבוץ גליות של ישראל כמ\"ש מי זאת עולה מן המדבר מדבר העמים כו' וכמ\"כ בחינת גלות של התורה מאחר דאורייתא מתקשרא בקב\"ה וישראל באורייתא דג' קשרין הללו כולא חד וענין גלות התורה היינו ג\"כ ענין פיזור ופירוד ההלכות עד שא\"א למצוא הל' ברורה כלל כי מפני הפיזור לא יוכלו לברר דבר ההלכה כמו שמצינו בכל הפילפולים שבגמ' שמקשה ורמינהו מפני שאותה ההלכה נתפזרה במקומות הרבה ויש לה סתירות וקושיות מזו על זו בדין והלכה א' והתירוצים לברר אותה הוא בא ג\"כ ממה שמוצא דוגמתה במקומות מפוזרים כמו כל ת\"ש שבגמר' שדין זה תוציא מדין כמוהו הנמצא במקו' אחר וכה\"ג כל ענין הפילפול שבגמרא וזהו רק מפני בחי' פיזור ההלכה עד שא\"א לעמוד על בירורה עד שמתרץ הכל דהיינו שמעמיד כל א' על מקומו וכמו שמתרץ ל\"ק כאן כו' (וכמ\"ש במ\"א שזה כמו סילסול בשערו' שמפריד הדיבוק והבילבול"],[2500660553,"כו' כך פיזור ההלכו' נקרא בילבול שאין א' על מקומו שזהו עיקר ענין הגלות כמו סנחרב שבלבל כל האומות להושיב אומה זו במקו' זולתה שזהו עיקר הגלות כאשר גולה ממקומו כידוע וד\"ל) וא\"כ יובן שתורה היא ג\"כ בגלות שאין כל דין והלכה נמצאת ברורה במקומה אלא בבחי' פיזור ובילבול גדול וקיבוץ הגלות של ההלכות הוא בחי' בירור ההלכות להעמיד כל א' על מקומה ולא יהיה לה סתירה ממקום אחר כלל כו' וד\"ל (וכמו שא' במחשכי' הושיבני זה תלמוד בבלי כו') ודוקא תורה שבע\"פ מל' קרינן לה בה עיקר הגלות וצריך בירור יותר בזמן הגלות כידוע דשכינה הוא בחי' המלכות וגלות השכינה וישראל ותורה שבע\"פ הכל שרש א' כו' וד\"ל. וזהו והיה עקב תשמעון את המשפטים האלה. פי' בזמן עקבות משיחא שהוא סוף כל הבירורים דרפ\"ח כו' כאשר יבורר הכל מראש עד סוף הכל בבחינת העקביים ג\"כ כנ\"ל אז תשמעון את המשפטים כו' שיהיה אז בחי' קיבוץ ואסיפה לפיזור ובילבול ההלכות דתושבע\"פ שנקרא משפטי' כנ\"ל דתרגום משפט הלכתא וז\"ש תשמעון את המשפטים כו' כמו וישמע שאול כו' שיתקבצו קיבוץ גלות התורה לידע הלכה ברורה במקומה בלי פיזור ובלבול ממקומות הרבה (וכמו שאמרו שקודם החורבן הרבה היו יודעין הלכות ברורות בלי פילפול כלל ונקרא אשכולות איש שהכל בו עד ב\"ש וב\"ה שרבו תלמידי' שלא שמשו כל צרכן הוצרכו לפילפול עד בימי אביי ורבא שנתרב' הפילפול ביותר ואע\"ג דלכאורה אמר בכ\"ד קושיות וכ\"ד פרוקי רווחי שמעתת' ביותר אך עד שמברר גודל הבלבול שבפיזו' ההלכו' אין ההלכה ברור' כלל והראשונים היו יודעים סוף דבר ההלכה הבא לידי בירור ע\"י הפילפול הרב מפני שהיו יודעים כל הלכה כמו שהיא בשרש מקומה וע\"כ לא היה להם קושיות ובילבולי' בלימודם כלל וכמ\"ש במ\"א שהפילפול זה ענין הוצאת מים מן הסלע ע\"י ההכאה שזה היה חטא משה ואהרן שלא אמרו אל הסלע להקדישני כו' וד\"ל) וז\"ש ערוכה בכל ושמורה פי' ערוכה בכל שתהיה ההלכה ברורה וערוכה בכל בלי יצא"],[2500660554,"ממנה בחי' פיזור ובלבול להיות קושי' וסתירה שהיא מסטר' דקליפה וז\"ש ושמורה בפ\"ה בלי גימגום ואז נק' שמורה מיניקות החיצונים כו' משא\"כ אם אינה ברורה וערוכה אינה שמורה מן החיצונים שזהו ענין גלות התורה כמו גלות השכינה וישראל כו' וד\"ל. והיינו שאמר והיה עקב תשמעון כו' ושמרתם שבקיבוץ גלות התורה אז ושמרתם מיניקות החיצונים כמ\"ש ערוכה בכל ושמורה וד\"ל:\n(נה) <b>והנה</b> אמר כאן ג' דברים תשמעון ושמרתם ועשיתם שמיעה ושמירה ועשיה שהן ג' מדריגות דמחשבה דו\"מ כנ\"ל. והנה כל ג' מדריגות הללו דשמיעה ושמירה ועשי' הכל אמו' על מצות ת\"ת בחי' שמיעה הוא בחי' הבנה בעיון שבמוח הבינה (כנ\"ל בענין שמע ישראל כו' השמע לאזניך כנ' באריכות) לעיין ולעמוד על הדבר היטב איך הוא ומה הוא עד שיברר הדבר הלכה מכל סיג וקושיא לבא אל אמיתת הדין וההלכה הברורה וזהו מצות הגיון שבתורה כמ\"ש והגית בו כו' בחי' עיון שהוא פנימיות בינה שמברר ההלכה בתכלית הבירור עד שתהא ההלכה פסוקה בלי שינוי לנטות ימין ושמאל כי אין להשיב עליה לסותרה באיזה קושי' כלל וכלל ונמצא שבבירור הלכה דוקא אז בא עיקר גילוי רצון העליון שבעצמות המתגלה בהלכה שנקרא אורח ודרך כנ\"ל באריכות אבל כל זמן שלא באה לידי בחי' בירור לתכלית האמת שבה עדיין לא נודע ונגלה כלל בחי' רצון העליון שבה אם כך או להיפך מפני שיוכל להשתנות מטמא לטהור ומפסול לכשר עדיין וכה\"ג מאחר שלא נברר עדיין לתכלית אמיתתה רק כאשר נשלם תכלית בירורה אם כשר או פסול בכל פרט ופרט כל דבר על בורי' היטב אז נגלה בזה אמיתת רצון העליון כמו שהוא למעלה ממש לאמיתתו בלתי שינוי ותמורה מרצון לרצון הפכי כו' וא\"כ הרי בבחי' העיון שמברר ממשיך גילוי רצון הפשוט בהלכה פסוקה זו והרי זה כאילו עשה רצון מחדש לרצון העליון הפשוט שבדין"],[2500660555,"והלכה זו (וכנ\"ל דשרש התורה בבעל הרצון לגלות עצמות הרצון שבו כו') מאחר שהדבר תלוי באופן הבירור שלו בעיון דבינה אם כשר או פסול הרי כפי אופן שבירר כך יומשך בחי' הרצון העליון הפשוט בדין זה אם כשר או פסול ונק' עושין רצונו הפשוט שבמצות כו' (שלמעלה מעושין רצונו ש\"מ שע\"י המצות כנ\"ל וד\"ל) ולכך תלמוד גדול שמביא לידי מעשה פי' שמביא וממשיך להיות בחי' רצון העליון הפשוט במעשה דין והלכה זו דוקא כפי אופן שבירר ע\"י הפלפו' שבתלמוד דוקא (ולכך אמר תלמוד דוקא ולא סתם תורה כו' וד\"ל). וזהו שאמר תשמעון בחי' שמיעה דבינה הנק' עיון והוא ג\"כ ענין אסיפ' וקיבוץ שהוא בחי' הבירור של גלות התורה מבחי' הפיזור והבילבול שלה שבא' בהעלמות רבות מפני הקושיות עד שאין הלכה ברורה כנ\"ל וע\"י העיון היטב מתקבצין כל הדינין וההלכות להיות כל אחד על מקומה דוקא כנ\"ל באריכות וד\"ל. וזהו מדריגה הא' בחי' מחשבה שהוא העיון וההגיון דמחשבה דבינה כנ' ומדריגה הב' היא בחי' שמירה שהוא בבחי' הדיבור בפה דוקא כמ\"ש ערוכה בכל ושמורה שמירה זו בפה דוקא כו' כי מתניתין מלכתא כמלך שגוזר ואומר בפה ואז כן יקום אבל כל זמן שלא הביא מחשבתו בדיבור אינ' כלום כך תורה שבע\"פ מל' קרינן לה שבפה אז נתקיים דבר מלך לבא לידי מעשה להיות הכשר כשר והפסול פסול וטמא טמא יקרא ולא טהור כו' וזהו עיקר פסק ההלכה כשבאה בדיבור בפה וזהו עיקר קיבוץ גליות ההלכות שלא להתבלבל עוד מטמא לטהור ומפסול לכשר באמרו בדיבור דוקא זה כשר וזה פסול אבל בעיון שבמוח גם שכבר נברר להיות זה כשר כו' עדיין אין זה פסק גמור למעשה אלא כשבא בדיבור דוקא שאז בא לידי מעשה כמלך שגוזר או' שכך יקיימו בפ\"מ שיהיה אז הקיבוץ לכל א' על מקומו הכשר במקומו והפסול במקומו כו' בבחי' המעשה בפ\"מ דוקא וה\"ז כמשל המלך שגוזר לקבץ הנדחים שלא במקומן להעמיד לכל א' על מקומו ולא"],[2500660556,"יגלה בגלות עוד שהעיקר הוא בקיום הדבר בפועל ממש להעמיד לכל א' בפועל ממש כו' והקיום בפועל ממש אינו אלא כשבא דבר מלך בפה לגזור אומר לעשות כך וכך כו' דהיינו זה יתעלה כפי מקומו למעלה וזה טמא יקרא וירד למטה ולא יעלה למעלה בעולם היחוד וזה טהור ויתעלה לעולם היחוד כו' וכמ\"ש במקום אחר וד\"ל. ונמצא ג' מדריגות הללו דשמיעה ושמירה ועשי' א' הוא רק שיורד בהשתלשלות דמחשבה דו\"מ אבל עיקר שלימות הענין הוא בדו\"מ ששם ודאי נפסק הדבר ונבדל בין טמא לטהור לגמרי ע\"כ עיקר השמירה מן החיצונים הוא בדיבור בפה כנ\"ל בפי' ערוכה בכל ושמורה כו' ויותר מזה הוא בסוף מעשה בפ\"מ להבדיל בין טו\"ר טמא וטהור כו' שבסוף מעשה דוקא נעוץ תחלת המחשבה שהוא תחלת הרצון הפשוט שבדין והלכה זו כידוע וד\"ל וכשאדם לומד איזה דין במחשב' ודיבור שזהו עיון וגרסא בפה יש כאן שמיעה ושמירה ובחי' עשי' היינו מה שכל פיזור חלקי ניצוצות נפשו האלקי' מתקבצים בפ\"מ מכל מקומות שנדחו שם בעניני עוה\"ז ע\"י שמקשרם ומאספם בדבר ה' זו הלכה שאו' בשעה זו וזה שאמר רב ששת חדאי נפשאי לך קראי לך תנאי כו' שאז נקר' תורתו אומנתו שכשמברר רפ\"ח כו' בפועל ממש אז ניתנה לו במתנה כו' וד\"ל:\n(נו) <b>וזהו</b> ושמר לך ה' אלקיך את הברית ואת החס' אשר נשבע לאבותיך כו'. דהנה לכאורה אין הפשוט מובן במ\"ש והיה עקב תשמעון כו' בעבור זה ושמר לך את הברית וכו' דמה שייכות יש לזה עם זה כו' אך הנה מבואר למעלה דלנגד ג' מדריגות דשמיעה ושמירה ועשי' שהן מחשבה דיבור ומעשה כנ' אמר שבעבור זה יומשך מלמעל' למטה ג\"כ ג' מדריגות כאלה בבחי' מחשבה דיבור ומעשה שנק' שמיעה ושמירה ועשיה והוא מ\"ש ג\"כ ג' מדריגות ברית וחסד ושבועה כו' וזהו את הברית ואת החסד"],[2500660557,"אשר נשבע כו'. אך יש להבין איך מבחי' ג' מדריגות דמחשבה דו\"מ הנ\"ל שמלמטה למעלה יומשך ג\"כ מלמעלה למטה ג' מדריגו' דברית וחסד ושבועה כו' וגם יש להבין מ\"ש ושמר לך שמירה זו מה היא כו' והנה תחלה יש להבין בענין ג' מדריגות הללו דברית וחסד ושבועה כו' מהו ההפרש בין זה לזה. בהיות מבואר למעלה בענין כריתת ברית שעושין שני אוהבין נאמנים באהבתם עד מיצוי הנפש כדי שע\"י מעשה כריתת ברית לא יבוטל אהבתם לעולם גם אם יתרחק מאד וישכחו זא\"ז או יביאו דברי נרגן ביניהם או יעשה א' רעה לרעהו או יעשה א' דבר רע שראוי לשנאה וריחוק כו' עכ\"ז רק הכריתת ברית לא יניח לעזוב את האהב' כו' דלכאורה זהו דבר פלא ביותר דמה מועיל המעשה גשמי שעושין בכריתת ברית זו כמו לעבור יחד בין ב' גזרים וכה\"ג דממ\"נ אם האהבה עזה עד מיצוי הנפש ממש כו' ממילא לא תבטל ולא תעזב מפני שום דבר בעולם לא מצד הריחוק ולא מצד דברי נרגן או מעשה רע וכה\"ג ולמה צריך למעשה דכריתת ברית כלל ואם אין האהבה בתוקפה כ\"כ עד שיוכל להיות בה שינוי ותמורה להתהפך לשנאה מצד איזהו דבר מה המפריד ומרחק כו' א\"כ מה מועיל המעשה גשמי דכריתת ברית כו'. אך הנה האמת הוא דגם אם האהבה עזה ותקיפ' עד מיצוי הנפש שלא תבטל משום דבר מפריד כו' מ\"מ אין זה רק בשעת תקפה דוקא שאז לא יתבטל לגמרי מכל וכל כמו מאהבה לשנאה וכה\"ג אבל יוכל להיות שדבר המפריד יעשה סיבה להקטנת אור האהב' למעט אור תקפה מעט מעט ולהחליש כחה מאד עד שתתעלם בהעלם כל עיקר כחה ולא ישאר ממנה רק תכלית מעוטה בבחי' רשימו בעלמא שזהו תכלית הקטנות ואז כשהיא בבחי' אהבה זוטא בתכלית הקטנות יוכל לבא עוד גם לידי פירוד והתחלקות ע\"י סיבת דבר הגורע אורה עד שמכבה אורה לגמרי עד שתהפך מאהבה לשנאה וכה\"ג כמו ע\"ד דוגמא ב' בנ\"א אוהבים נאמנים בנפשם כאהבת דוד ויונתן"],[2500660558,"שבודאי בשעת תוקף אהבתם בקרבתם זע\"ז לא יועיל שום דבר בעולם להפריד בין הדבקים אך כאשר מתרחק איש מרעהו זמן רב כמו כ' או ל' שנה וכה\"ג עד ששכח איש על רעהו לגמרי ולא נשאר כלל באור האהבה שום תוקף וכח אלא רק רשימו בעלמא וגם זה בהעלם גדול וכל עיקר תוקף האהבה נסתלק ונשאר בבחי' מקיף בהעל' מאוד מאד עד אשר גם כשיזכרו אותו על אודות האהבה לא תתעורר כלל בלבו כי נשכחה לגמרי מכל וכל מלהיות בבחי' גילוי רק בהעלם בבחי' מקיף לבד ואז ודאי יוכל להיות פירוד בין הדבקים ע\"י דברי נרגן או סיבה אחרת להתהפך מאהבה לשנאה כו' לפי שמשך הזמן הזה עשה מיעוט והקטנה מאד כו' וכך הוא בסיבת דברי נרגן שמחלישים כח ותוקף האהבה מעט מעט עד שתשאר בבחי' הקטנות ביותר עד שבעשות לו רעה ממש יהפך לשונא וכן מסיבת מיאוס מעשיו הרעים מחלישים כח האהבה עד שנמאס בעיניו לגמרי לשנוא אותו כו' כמו אב לבן כשהרע מעשיו מאד שנהפך לשונא ולאכזר כו' וד\"ל. אך לזה מועיל ענין הכריתת ברית שע\"י כריתת הברית גם אם נשכחה האהבה לגמרי תתעורר מחדש ממש כשיזכור על הכריתת ברית דוקא. והטעם הוא לפי שבחי' כריתת ברית גם כשעושה מעשה לבד בגשמיות אבל שרש זה המעשה מורה על בחי' ההתקשרות עצמיות דוקא דהיינו שכל עצמות הנפש מתקשרת בעצמו' הנפש זולתו כמו ונפשו קשורה בנפשו הרי הקשר הזה מורה חיבור וקשר עצמי שהוא התאחדות עצם ב' הנפשות כאילו הן נפש א' ממש ואין קשר הזה בבחי' פרט מכחות הנפש כמו הרצון או השכל כו' שיש כאן ב' דברים א' שהמקושר ברצון לעשות רצון זולתו הרי הן ב' רצונות נבדלים במהותן רק שמתקשרין יחד והב' שאין התקשרות זו רק ברצון לבד ולא בשאר דבר זולתו ומכ\"ש שאין התקשרות זו נוגע לדבר מה הנוגע בעצמו' הנפש שיוכל להיות שא\"א לו לעמוד בו כלל אבל ההתקשרות של עצמות הנפש"],[2500660559,"ממש הרי ב' הנפשות אינן נבדלים אלא נעשין כנפש א' ממש להיות שבחי' העצמות של הנפשות מתקשרים והיו לנפש א' ממש ונק' התקשרות זו בבחי' יחידה שבנפש וכמו ע\"כ יעזב איש כו' ודבק באשתו והיו לבשר א' וכן ותדבק נפשו בדינה כו' וכה\"ג אהבת דוד ויהונתן שא' נפלאה אהבתך כו' וד\"ל. ולהיות כן גם כאשר נשכח ונתמעט האהבה לגמרי ע\"י הריחוק במשך הזמן הרב כנ\"ל או ע\"י סיבת הפירודים הנ\"ל מכל מקום בחי' ההתקשרות העצמות הזאת שנקשר ב' הנפשות כנפש א' בבחי' יחידה שבהם יש בכחה להחזיר אור תוקף האהבה להיות בגילוי גמור כמקדם בכל האופנים שלא יועיל פירוד בין הדביקים כלל דהיינו שעושה בחי' התחדשות ההתעוררות אהבה שתתחדש להיות כמו קודם שנפרדו שהיה אהבתם עזה עד מיצוי הנפש ומזה יש הוראה גמורה שלא נסתלק תוקף האהבה העזה לגמרי אלא נשאר בבחי' מקיף בהעלם עכ\"פ כו' והגם שכאשר יזכרו אותו על אודות האהבה העזה לא תתעורר כלל בלבו כי נשכחה לגמרי מכל וכל כנ\"ל מ\"מ ע\"י מעשה כריתת ברית דוקא כשעשו מעשה לזכרון אהבה והתקשרות עצמיות הנפשות הנ\"ל אז כאשר יזכירהו על מעשה כריתת ברית הזאת דוקא אז יש בכחה לעשות מחדש התעוררות האהבה העזה כמקדם בגילוי גמור שלא תתבטל לעולם מן הלב והיינו מפני שביכולת המקיף להחזיר אור הפנימי מחדש כו' ודוקא מקיף דיחידה מפני שבחי' יחידה היא עיקר והמקור הכללי שכל הכחות כלולים בה וא\"כ גם שנתמעט הארת האהבה בבחי' הקטנות מאד תוכל להחזיר האור להיות בבחי' הגדלות (כי כל ט\"ס חב\"ד כו' גדלות וקטנות כלולי' רק בחצי התחתון שביחידה וכריתת ברית היינו כתר שבכתר ולזה בכח פנימיות הכתר דוקא להחזיר פנים בפנים ביחוד דמוחין דגדלות כו' כנ\"ל והוא בחי' התקשרות העצמות של הרצון ולא התקשרות הרצון לבד כו' וז\"ש לעברך בברית ה' אלקיך שהוא בחי' התחלקות הכתר לחצאין כמ\"ש"],[2500660560,"במ\"א וד\"ל) ונמצא שאע\"פ שעיקר ענין כריתת ברית הוא רק זכרון האהבה מ\"מ כשיזכירוהו בלא כריתת ברית אינו מועיל כלל אע\"פ שהיה ביניהם בחי' התקשרות עצמיות אבל נשאר בבחי' מקיף לבד כו' אך כשעשו מעשה דכריתת ברית מועיל הזכרון של האהבה לחדש אותה כמבראשונה כו' מפני שע\"י המעשה הזאת יוכל לבא בחי' המקיף של ההתקשרות העצמיות למטה להועיל לכח הזכרון לעורר את תוקף האהבה מחדש בכל תקפה וגבורתה הקדום וא\"כ הרי מובן שיש יתרון למעשה הגשמיות דכריתת ברית מגופה של עצם ההתקשרות אע\"פ שהוא כמו שעושין אות וסימן לזכרון לבד מ\"מ מועיל יותר מגופה של ההתקשרות שתוכל להבטל לגמרי כנ\"ל וזכרון הברית אין לו ביטול והפסק לעולם כו' וד\"ל. ומעתה יש להבין ענין החסד ומהו ההפרש בין ברית לחסד שהוצרך לומר את הברית ואת החסד כו'. אך הנה כמו שמבואר למעלה בבחי' התקשרות עצמיות של הנפשות שמתאחדים מצד העצם לבד ולא מסיבת איזה דבר חוץ מן העצמות הנה אנו רואים שיוכל להיות כח התקשרות פנימיות ועצמיות כזאת הבאה מן הצד מדבר אחר ולא מצד עצם הנפש כלל גם כי רחוקים היו לגמרי בטבעם ובמהותם אך ע\"י אמצעות דבר אחר הוא שמתקשרים יחד והיו לנפש א' ממש וכמו ע\"כ יעזב כו' ודבק באשתו שמתאחדים ומתקשרים ב' הנפשות דמשפיע ומקבל מצד דבר אהבת ההשפעה שביחודם תמיד מזה אהבתם נעשית בבחי' עצמי' ופנימית ממש כמו התקשרות העצמו' הנ\"ל וכמו באהבת דוד ויהונתן שנא' אהבת נפשו אהבו כו' שזהו כמו אהבת המשפיע שתדבק נפשו בנפש המקבל וכמ\"ש ודבק באשתו או כמו ותדבק נפשו בדינה כו' וכן אהבת המקבל למשפיע שכורתת ברית למי שעשאה כלי כו' ונק' בזהר אתדבקות רוחא ברוחא בבחי' התדבקות והתקשרות עצמיות כנ\"ל וכן מבחי' השפעת הרב לתלמיד כל ימיו עד שעשאו כלי כמו פני יהושע כפני לבנה שקיבל תמיד מפי"],[2500660561,"משה פני חמה כו' כמ\"ש לא ימוש מתוך האוהל כו' וכך בכל אהבת משפיע ומקבל והנה כמ\"כ יש בחי' התקשרות עצמיות שנולד מדבר ריבוי החסד והטוב ביותר דהיינו הפלגת ריבוי החסד והטובה עד שכל נפשו תלויה בחסד זה כמו להחיות רוח שפלים העני והאביון ברב טוב וחסד כל הימים שפיקוח כל נפשו ונפשות ביתו תלויה בחסד זה שמחיה לנפשו בחיות חדש בכל יום או רב החסד להציל האדם מן המות בראותו שטובע בנהר או לסטים קמים עליו או נידון להריגה עפ\"י מלכות והאיש החסדן בטבעו נותן נפשו עליו להצילו מן המות וכשניצול על ידו אין לך חסד גדול כזה שהשיב לו נפשו וכן החולה המסוכן כשירפאוהו ויקימנו ממות לחיים וכה\"ג הרי כל אלה עושה בחי' התקשרות עצמיות בנפש המקבל החסד וגם נפש המשפיע החסד נקשרה בנפש זה שע\"י חסדו נעשה מחדש וא\"כ הרי מובן שעפ\"י בחי' החסד והטוב יוכל להיות ג\"כ בחי' התקשרות עצמיות ולכך נקרא בשם חסד כי החסד הוא בחנם שלא ע\"י סיבת אהבה בתחלה כמו המציל לזולתו מן המות שלא היה זה מצד אהבה כלל אלא רק חסד פשוט וכן המחיה לנפש עני וכה\"ג ויש חסד שאינו נעשה רק מצד אהבה ולפי ערך האהבה אם רב או מעט כן יהיה ערך החסד אם רב או מעט כו' אבל החסד האמיתי הוא החסד אשר עושה בחנם שלא מצד התקשרות אהבה כלל שהוא בחי' חסד פשוט ועצמי בלתי מורכב בדבר מה גם לא באהבה או שכל ותענוג ורצון כו' וזהו כמו החסד שנעשה מצד כריתת ברית בזכרון אהבה העצמי הנ\"ל או מצד התקשרו' דמשפיע ומקבל שהוא למעלה מן השכל והטעם ע\"כ לא יכלה כח החסד כי אין להתקשרות כזאת ביטול והפסק לעולם כו' וכך אין לחסד פשוט הזה ביטול והפסק לעולם שהרי אנו רואים בחוש שא\"א לאדם לשכוח על רב טוב חסד של רעהו שהצילו ממות וכה\"ג א\"כ ה\"ז כמו בחי' התקשרות עצמותו הנ\"ל וד\"ל. ועוד יש חסד שבא"],[2500660562,"מצד אחר ואין לו ביטול ג\"כ והוא כאשר ראה בחבירו שמסר נפשו בסכנת מות ממש בשבילו או סבל רוב צער ועינוי או ריבוי טורח ועבודה קשה שנגעה עד הנפש רק בשבילו כו' שלזה אין שיעור לחסד שצריך להשיב לו כו' וכן עוד יש חסד שאין לו שיעור כאשר ראה בהפקירות זולתו להניח כל אשר לו ולילך אחריו גם בסכנות כו' שזהו בחי' התקשרות עצמות כמו זכרתי לך חסד נעוריך כו' לכתך אחרי במדבר כו' וכמו רות שהלכה אחרי נעמי עד שא' כ\"א המות יפריד כו' שבודאי אין שיעור לחסד שצריך לעשות לעבדו הנאמן שהשליך נפשו מנגד כו' והולך אחריו לשרתו ולעבדו וכה\"ג יש ריבוי אופנים בחי' החסד שאין לו שיעור שנולד מצד וסיבה שחוץ מן עצמות הנפש אלא נחשב כמו התקשרות העצמית הנ\"ל וה\"ז בחי' התקשרות הנקנה מצד בחי' התפשטות עצם הנפש במה שמתקשרת בהתפשטותה ודבקותה בנפש זולתה לבד כמו ע\"י סיבת ההשפעה או ע\"י ההצלה דמות הנ\"ל או מסיבת הפקירות נפש חבירו בעבורו כו' וכהאי גוונא שכל זה בחי' התפשטות ולא בחי' העצמיות אבל כל בחי' העצמות מתפשט על כן כמו התקשרות עצמות יחשב שאין לו שיעור ומדה ולא הפסק וביטול לעולם כנ\"ל וד\"ל:\n(נח) <b>וזהו</b> ושמר לך את הברית ואת החסד כו' הברית הוא בחי' התקשרות עצמות הנ\"ל שאינו בא רק מצד בחי' העצמיות לבד ולא משום סיבה מן הצד כלל רק מצד ששרש ועצם א' הן מפני שממקו' א' יצאו וכה\"ג. וכך יובן למשכיל למעלה בבחי' התקשרות דנשמות ישראל בשרשן בעצמות אא\"ס ב\"ה כמארז\"ל ישראל עלה במחשבה ה\"ז בחי' התקשרות עצמיות מצד עצם הנשמות ישראל ומצד עצמות אא\"ס שהן כמו עצם א' ממש כידוע בפי' ישראל לי ראש כו' (וז\"ש במדרש ז' דברים קדמו לעולם תורה ותשובה ובנין בהמ\"ק כו' ומחשבתן של ישראל קדמה לכולן כו') וע\"ז נעשה"],[2500660563,"כריתת ברית לאברם בעברו בן הבתרים בבחי' המעשה דוקא לעורר זכרון האהבה והתקשרות עצמיות הזאת שעלו ישראל במחשבה העצמי' כו' שלא תבטל לעולם גם כי תקטן ותתמעט האהבה או תשכח לגמרי מצד עוצם הריחוק או בסיבת הקיטרוגים הרבים העושים פירוד בין הדבקים ומחלשים תוקף התקשרו' האהב' או בסיבת מעשים הרעים והשנואים בעיני ה' מאד עכ\"ז לא מאסתים לכלותם להפר בריתי אתם כו' כי בחי' הרשימו דקטנות הנשאר תתחדש להיות בתוקף ההתקשרות כמבראשונה ע\"י זכרון הכריתת ברית שהיו בפ\"מ דוקא מטעם הנ\"ל שמעשה זו גורמת להביא זכרון האהבה שתתחדש בתקפה ומועיל לכח הזכרון לעורר את תוקף האהבה כמקדם ממש משא\"כ בלא כריתת ברית שתוכל גם התקשרות העצמי' להבטל כו' כנ\"ל באורך וד\"ל. אך הנה גם על מעשה הכריתת ברית יוכל לשכוח וצריך להזכירו וזהו ושמר לך את הברית כו' שהוא לשמור זכרון הברית ונקרא שמירה כמו ואביו שמר את הדבר שהמתין ומצפה ושמר הדבר בלבו ולא נשכח ממנו כך ושמר לך את הברית להיות בזכרון תמיד ולא ישכח לעולם כו' וכמו ששומר זכרון הברית כך שומר להחסד שהוא בחי' החסד הפשוט העצמי שבלתי מורכב בדבר מה שאין לו שיעור כלל כי הוא בבחי' א\"ס ממש כמ\"ש חסדי ה' כי לא תמנו כו' וזהו ואת החסד בה' הידוע והוא בא מצד בחי' התפשטות של עצמית כשכל העצמיות מתפשט ע\"כ גם הוא בבחי' א\"ס כמו כי חפץ חסד הוא כו' וזהו מחמת התקשרות שנלקח ונקנה מצד בחי' התפשטות כל העצמיות דמשפיע ומקבל ביחודם וכמו אהבת דוד ויהונתן או משה ויהושע וכה\"ג בכל משפיע ומקבל שנפשותיהם דבוקים והיו לנפש אחד שזהו כמו בחי' התקשרות שמצד העצמיות יחשב כנ\"ל וכידוע דכנסת ישראל נקר' אשה והקדוש ברוך הוא נקרא איש כמה שכתוב ביום ההוא תקראי לי אישי והוא בחינ' יחוד קוב\"ה ושכינתיה בבחי'"],[2500660564,"התקשרות ואתדבקות רוחא ברוחא כו' ע\"כ א' ושמר לך את החסד שהוא ג\"כ בבחי' א\"ס מאחר שכל עצמות אא\"ס נמשך ומתפשט בהשפעתו או כמו חסד פשוט שעושה להחיות לעני או להציל מן המות וכנ\"ל שאינו מורכב בדבר מה גם לא באהבה ותענוג כו' כנ\"ל שאין לו שיעור והפסק וביטול לעולם או כמו החסד שבא מצד הפקירות זולתו כו' כך כתיב זכרתי לך חסד נעוריך כו' שכמו התקשרות עצמיות יחשב כנ\"ל וז\"ש כי ההרים ימושו כו' וחסדי מאתך לא תמוש כו' חסדי הפשוט העצמי כו' משא\"כ חסד שתלוי לפי אופן האהבה וזהו ההרים ימושו כו' וכמו אהבה התלויה בדבר כמו הטעם והשכל או הרצון ותענוג שאם יבטל הדבר שתלויה בו כמו התענוג או השכל כו' בטלה אהבה זו לגמרי וממילא יבוטל החסד וז\"ש ההרים ימושו אפי' ההרים הגבוהים כמו הררי קדם שנקרא בזהר טורא חשוכא שברצון ותענוג כו' כמ\"ש במ\"א אבל חסד הפשוט שבלתי מורכב גם בתענוג כו' רק חסד פשוט ועצמי לא תמוש שאין לו ביטול עולם לפי שבא מכח של התקשרות העצמיות כנ\"ל וד\"ל. והנה השמירה לחסד זה בהכרח שזהו כמו ושמר לך את הברית הג' שצריך להזכירו תמיד דהיינו גם אם נשכח הדבר לגמרי כמו סיבת הריחוק או ע\"י קיטרוגים ומעשים רעים כנ\"ל צריך להזכירו והשמירה לזכרון זה הנה בבחי' כריתת ברית היינו לזכור על מעשה דכריתת ברית תמיד אבל בחי' התקשרות זאת שבבחי' ההתפשטות לא נעשה מעשה ע\"ז רק במ\"ת דכתיב אשר כרת עמך ברית כו' ע\"כ צריך שמירה מעולה יותר שלא ישכח והיינו מ\"ש אשר נשבע לאבותיך ושבועה זו עיקרה על בחי' החסד (כי על הכריתת ברית אין צריך שבועה כ\"כ כי לא יוכל להפר ברית אך על מ\"ש וחסדי מאתך לא ימוש ע\"ז צריך שבועה ג\"כ כי בלא שבועה הרי יוכל להבטל ג\"כ כמו שמבואר למעלה גם בבחי' התקשרות עצמיות שתוכל להבטל מצד ההקטנה בלא כריתת ברית כו' וד\"ל):"],[2500660565,"(נט) <b>והנה</b> עיקר ענין השבועה הוא רק בחי' ההתקשרות במעשה לבד כי הנה אנו רואים בחוש שאדם יוכל לישבע לעשות דבר מה גם שדבר זה הוא לנגד רצונו ושכלו ומדותיו ג\"כ כמו שנשבע לפזר הון רב לצדקה או להיות נכנע לזולתו הקטן ממנו באופנים שהן שפלות וירידה גדולה אליו ביותר או להיות לו קירוב וחיבור עם השנאוי ומאוס בעיניו ביותר וכה\"ג למחול לשונאו ולעשות לו טובה הרבה אשר השבוע' הזאת אינה באה מצד חפצו ורצונו כי לדבר שחפץ ורוצה ומתענג בו א\"צ שבועה כלל או לדבר שאוהב וחומד מצד שכלו שנוטה אל האהבה והחסד ג\"כ א\"צ שבועה כלל אך לדבר שאין לו רצון וחפץ כלל גם לא בשכל ומדות רק שמכריח א\"ע לדבר זה מצד ההכרח לבד וגם שהוא הכרח אין זה נגד הרצון לגמרי שא\"כ לא היה מכריח א\"ע כלל שאין מי שכופה אותו ע\"ז רק הוא מכריח א\"ע ומאחר שמכריח א\"ע ודאי שיש לו איזה רצון בו ע\"כ רוצה להכריח א\"ע שיהיה קשור בו מצד השבועה ואם לא היה לו רצון כלל לא היה מכריח א\"ע לקשר א\"ע בשבועה אלא מפני שרוצה להיות לו התקשרות באותו דבר שלא יוכל לחזור בו ע\"כ מכריח את עצמו בשבועה כידוע וכמו הנשבע ליתן הון רב לצדקה וכה\"ג שבוודאי אין פנימית רצונו בזה ולא חיצוניות הרצון ג\"כ אלא אדרבה קשה עליו הדבר ביותר אך מפני שרוצה להיות לו רצון זה ואין לו רצון ע\"כ קופץ ונשבע כדי שיהיה קשור לקיים בפ\"מ גם שזהו עכשיו נגד רצונו כו' ולפ\"ז הרי עיקר השבועה רק בחי' ההתקשרות בקיום פועל ממש במעשה לבד שהרי א\"צ שבועה רק כאשר כבר ניטל כל הפנימי' שהוא הרצון והשכל והמדות כנ\"ל רק שמכריח א\"ע לקיים הדבר בפ\"מ לבד כו' ועוד שייך שבועה גם בדבר שיש בו רצון וחפץ פנימי אך להביא הדבר לידי מעשה בפ\"מ היא שצריך לשבועה כי יוכל להיות שינוי הרצון והחפץ מהיפך להיפך או גם אם לא יהיה שינוי רצון בעצם אבל לידי מעשה לא ירצה להביא"],[2500660566,"אותו הדבר שרוצה מאיזה טעם וסיבה כידוע אך ע\"י השבועה שנשבע לעשות הדבר ההכרח לו להביאו לידי מעשה כי נתקשר בשבועה זו הגם שהוא נגד רצונו לענין מעשה או גם בגוף הרצון נעשה שינוי אבל השבועה תמסור ותקשור אותו כידוע והנה בדבר זה שהשבועה היא ההתקשרות במעש' עכ\"פ גדל כחה גם מכחה של כריתת ברית הנ\"ל דגם שכריתת ברית גדול כחה לעורר מחדש את תוקף האהבה כנ\"ל היינו דוקא בבחי' העצמי' של האהבה והרצון בלבד אבל לענין מעשה בפ\"מ צריך גם זה לשבועה לקשר א\"ע להביא הדבר לידי פ\"מ וראיה מכריתת ברית לאבות על דבר ירושת הארץ כמ\"ש וגם הקימותי את בריתי לתת להם את ארץ כנען כו' ואעפ\"כ הוצרך לשבועה ג\"כ וכמ\"ש כאן ושמר לך את הברית כו' אשר נשבע לאבותיך דמשמע דקאי אשר נשבע גם על דבר הברית וגם שא\"א להפר ברית כמ\"ש לא מאסתים כו' לכלותם להפר בריתי כו' היינו לכלותם דוקא שזהו מעשה לסתור הכריתת ברית ולהפר אותו אבל בשביל קיום דבר מה של חסד וטוב גם שכרת ברית ע\"ז צריך שבועה ג\"כ לקיים דבר הברית וז\"ש אשר נשבע לשמור הברית להביאו לידי מעשה ונמצא שהשבועה חלה גם על הברית והחסד בין בתקפה בין במיעוט' בתכלית מטעם סיבת הנ\"ל השבועה תחזיק ותקים את הדבר בבחי' המעשה עכ\"פ גם שלא נשאר באהבה והתקשרות רק רשימו בעלמא עד שתוכל להבטל כשלא יזכור על הברית והחסד כו' מ\"מ לא תבטל לענין מעשה מצד השבועה אע\"פ שבבחי' פנימיות בטלה לגמרי כו' וד\"ל. ומפני שנעוץ תחלתן בסופן כשבא הדבר בסוף מעשה בפ\"מ דוקא ע\"כ השבועה שהוא ההתקשרו' במעשה זהו שלימות תחלת הרצון העצמי שהוא התקשרות העצמיות שבכרית' ברית הנ\"ל וז\"ש ושמר לך את הברית כו' שעיקר שמירת הברית ושלימותו הוא אשר נשבע ובאמת קאי ושמר על השבועה ג\"כ לשמור לעשות כו' והיינו ג' מדריגות דמחשבה דו\"מ ג\"כ כי"],[2500660567,"הנה בחי' התקשרות עצמיות הוא במחשבה שהוא הרצון העצמי מצד עצמו' ממש והחסד הוא בחי' דיבור כמו את הויה האמרת היום האמרת פועל יוצא שהוא בחי' התפשטות של עצמות אא\"ס בהשפעת אורו וז\"ש האמרת כמו במ\"ת שירד על הר סיני וידבר אלקים כו' שכל בחי' גילוי אור מן העצמות נקרא בחי' דיבור בחי' יצירה כו' כידוע והוא הנקרא חסד שהוא בא בגילוי בלב והחסד בה\"א ידיעה היינו בחי' רב חסד הפשוט שבעצמות שבא לידי גילוי כנ\"ל בפי' וחסדי מאתך לא ימוש כו' והוא מצד התקשרות הנקנה כו' כנ\"ל באורך ומדריגה הג' הוא בחי' התקשרות במעשה שעל ידי השבועה דגם אם נשכח האהבה לגמרי ונתבטל מן הלב מכל וכל לא ימיש חסדו מלעשות אותו בפ\"מ עכ\"פ מצד השבועה וז\"ש אשר נשבע לאבותיך פי' נשבע ה' שיומשך חסד עליון בכנסת ישראל לעולם בבריאה יצירה עשיה עד שיבא לבחי' המעשה על כל פנים גם שבחי' פנימיות האהבה נשכח לגמרי מאיזה סיבה כנ\"ל וגם אם עדיין נזכר על האהבה מפני זכרון הברית שמעורר מחדש כנ\"ל עכ\"ז צריך לשבועה להביא לבחי' מעשה כי נעוץ תחלתן בסופן ע\"כ השמירה להביא לידי מעשה בפועל ממש הוא עיקר שלימות התחלה שהוא הפנימיות של ההתקשרות כו' וד\"ל. וזהו בעבור שתשמעון את המשפטים ושמרתם ועשיתם ג' מדריגות דמחשבה דו\"מ מלמטה למעלה כי התורה נקרא ברית כמ\"ש אלה דברי הברית וזהו בעיון דמחשבה שהוא בחי' התקשרו' עצמיו' המדריגה שבה שהוא בחי' כרית' ברית שבה כנ\"ל שהתורה מחבר עצמות הכתר דרעוא כו' בלי דבר מפסיק כלל כו' ובחי' דיבור שבה הוא גורם את ה' האמרת כו' מלמעלה למטה כנ\"ל ובחי' המעשה שבה שזהו ושמרתם כדי לעשות דוקא שהוא הסוף שעלה בתחלת הרצון והוא קיום הדבר הלכה לבחי' המעשה להיות זה כשר כו' כמלך"],[2500660568,"שגוזר לעשות דוקא כנ\"ל באורך מעורר מלמעלה למטה ג\"כ בחי' ההתקשרו' במעש' שזהו ענין ובחי' השבוע' אשר נשבע לאבותיך שהוא עיקר הקיום של הברית והחסד בין בתקפן בין במיעוטן כנ\"ל מפני שנעוץ תחלתן בסופן וסוף מעשה הוא שעלה במחשבה תחלה כו' וד\"ל. וזהו והיה עקב תשמעון כו' בזמן הגלות עקבות משיחא שהוא בחי' המעשה שאז תשמעון ודאי כנ\"ל מפני שהוא סוף הכל ונעוץ תחלתן בסופן כו' אז ושמר ה' אלקיך כו' אשר נשבע שישמור את השבועה להביא לידי מעשה דוקא כמו ושמרתם ועשיתם שמלמטה למעלה וד\"ל אך לכאורה אם כבר נשבע לאבות האיך יוכל לעבור שלא לקיים בפ\"מ גם אלו לא ישמורו לעשות את כל התורה כו' אבל הענין הוא משום דסוף מעשה זה דתורה עלה בתחיל' המחשבה וע\"ד כן נשבע לאבות לשמור להם הברית והחסד ע\"כ בחסרון מעשה למטה אין בחי' התקשרות שבועה במעשה למעלה כלל מאחר דנעוץ תחלתן בסופן דוקא ומ\"ש אשר נשבע כבר היינו לפי שבעקבות משיחא ודאי ישמרו לעשות כנ\"ל בפי' והי' עקב תשמעון שאז תשמעון ודאי כו' וד\"ל:\n(ס) <b>אך</b> הנה עדיין יש להבין מ\"ש ושמר לך מהו לך דוקא ומהו ענין שמירה זו דמפני מי צריך לשמור כו' אבל הענין הוא דשמירה זאת הוא בבחי' הדיבור כמו ענין ערוכה בכל ושמורה הנ\"ל שזהו בבחי' המשנה שבדיבור שלא יתפשט חוצה כשגוזר אומר זה כשר כו'. וזהו ג\"כ ושמר לך דוקא לישראל עם קרובו דוקא יהי' שמירה מעולה לעורר זכרון הברית ולא יתפשט חוץ לאוה\"ע כו' כי יהי' הבדל גדול בין ישראל לאוה\"ע במעלה ומדריגה נכרת לעין כל דוקא וזהו לעתיד לבא דוקא דכתיב ועמדו זרים ורעו צאנכם כו' שלא יעבדו ישראל עבודה גשמי' בפרנסה כלל אלא מלאכת' נעשי' ע\"י אחרים שהן אוה\"ע שנק' זרים כו' משא\"כ עכשיו שישראל עוסקים בפרנסה ע\"י עצמם כשאר האומות"],[2500660569,"כמ\"ש ואספת דגנך שאוסף בעצמו כו' ואין הבדל ניכר כלל בין ישראל לאוה\"ע. אבל לע\"ל יהיו נבדלים בערך על מין האנושי דאוה\"ע וכמ\"ש משה ונפלינו אני ועמך מכל כו' ואז נאמר זה הפסוק ושמר לך את הברית לך דוקא יהי' שמור ולא לזולתך כו' וד\"ל. וביאור הדברים הנה מבואר למעלה בפי' עושין רצונו של מקום שאז נאמ' ועמדו זרים כו' וכשאין עושין רצונו ש\"מ שאז נאמ' ואספת דגנך כו' דרצונו של מקום זה הוא בחי' הכתר הכללי שנק' רעוא דכל רעוין כו' שהוא מקור להיות בחינת מקום דממלא וסובב כו' וישראל עושין רצונו ש\"מ הזה מבעל הרצון עצמו כו' וזהו לע\"ל דווקא שאז יהי' בחי' גמר לעשיית הרצון ש\"מ הזה מבעל הרצון וע\"כ נאמר אז ועמדו זרים כו' שמלאכתם נעשי' ע\"י אחרים משא\"כ עכשיו שעדיין אין עושין רצונו ש\"מ הזה מבעל הרצון ולא נגמר עשיית הכת' הכללי הנ\"ל ע\"כ נאמר ואספת דגנך בעצמם עובדי' כו' ולזה לא נז' בכל מאדך בפ' זו משום דהא בהא תלי' כנ\"ל באורך. ולהבין טעם הדברים הללו הנה כתיב הנה ישכיל עבדי ירום ונשא וגבה מאד ופסוק זה לעתיד נא' על משיח שישכיל וירום כו' ויש כאן ה' מדריגות ישכיל וירום ונשא וגבה מאד ומבואר במ\"א דפי' ישכיל הוא בבחי' מקור כל החכמה שבאה בהשתלשלו' דאבי\"ע והוא בחי' ח\"ס דא\"א ירום בבחי' גולגלתא כת' דא\"א שנק' ירום כידוע ונשא בחי' ג\"ר דע\"י וגבה בחי' ג\"ר דא\"ק ומאד הוא בחי' מל' דא\"ס עצמו שהוא מקור לבחי' כת' דא\"ק כידוע וזהו מאד בהיפוך אותיות אדם דבריאה בחי' א\"ק כמ\"ש כי לא אדם הוא כי הוא בחי' המקיפי' שלו שלמעל' מראשו כו' וידוע דמשיח הוא בחי' מל' דאצי' ששרשה בכת' עליון כמ\"ש כתר מל' איהו כ\"ע והיינו עד בחי' מל' דא\"ס שהוא בחי' מקיף וכת' לכת' דא\"ק והוא עליי' היותר עליונה שנק' מאד בלי גבול דהיינו בבחי' עצמיות אא\"ס שהוא בלי גבול באמת כו' וכמ\"ש במ\"א וד\"ל:\nוהנה כאשר כללו' נ\"י יתעלו לעתיד"],[2500660570,"בבחי' מל' דא\"ס ע\"י משיח דכתיב בי' וגבה מאד כנ\"ל אז נאמר ועמדו זרים כו' לפי שאז דוקא יהיו נקראי' עושין רצונו ש\"מ מבחינת מל' דא\"ס לעשות בחי' כתר הכללי דא\"ק כו' שנק' ג\"כ רעוא דכל רעוין כנ\"ל וכשעושין רש\"מ זה אינן צריכין לעבוד' הבירורי' דרפ\"ח ניצוצו' כלל כי אין עבודת הברורים דרפ\"ח כו' רק ענין אסיפה וקיבוץ הניצוצו' קדושו' שנדחו ונתפזרו ברצון הזרו' דנפש הבהמית דנוגה כנ\"ל באריכות בפי' שמע ישראל כו' ובפי' תשמעון ואין האסיפה וקיבוץ כמ\"ש אם יהי' נדחך משם יקבצך רק ע\"י החכמ' משום דבחכמ' אתברירו דוקא והיינו ע\"י בכל נפשך שנולד מצד השכל וחכמה אלקי' שבהתבוננות דשמע ישראל כו' כנ\"ל אבל אז עדיין לא נקראי' עושין רצונו של מקום מבעל הרצון עצמו כו' רק ע\"י אהבת בכל מאדך דוקא בלי גבול למעלה מבחי' הרצון אלא בבעל הרצון עצמו אז נקרא עושין רש\"מ מבעל הרצון כנ\"ל באריכות וזהו שנא' ואספת דגנך כו' פי' דגנך הן פזורי ניצוצות הנשמות שנדחו ונתפזרו בעולם הפירוד כמו אם יהי' נדחך כו' וה\"ז כמו פיזור דגן התבואה ממש שנתפזר בארץ ונרקב ואח\"כ יצמחו רב תבואות מאוד ויאסוף אותם כך נמשל בחי' הבירורים של פיזור ניצוצות הקדושים בע' שרים דנוג\"ה כמ\"ש ימי שנותינו בהם ע' שנה כו' בבחי' אסיפה וקיבוץ תבואה שצמחה כו' כי נולדים בכל דור ריבוא רבבות ניצוצו' שמתבררים ועולים מלבושי' דנוגה כמ\"ש במ\"א באורך בפי' ואעש' אותך (שם) לגוי גדול כו' וכמ\"ש קדש ישראל ראשית תבואתו כו' (כי כללות נ\"י שרשם בחכמה שהוא בבחי' דגן כמו שא' אין התינוק יודע לקרות אבא עד שיטעום טעם דגן וכללות נ\"י נמשכו מבחי' אור אבא כמה שכתוב כי אתה אבינו וכידוע) ומה שכתוב כאן ג' מדריגות דגנך ותירושך ויצהרך הן ג' מדריגות שבכללות נשמות ישראל כהנים ולוים וישראלי'. וכידוע דשרש הכהנים בבחי' החסדי' דחכמה שנק' שמן ושרש הלוים בבחי'"],[2500660571,"בינה בחי' הגבורות שהוא בחי' יין וזהו תירושך ויצהרך יין ושמן ודגנך הן בבחי' ת\"ת בחי' ממוצע בין חסד וגבורה והוא בחי' קו האמצעי שכולל ב' הקוין דחח\"נ ובג\"ה כו' וכולן צריכין אסיפה וקיבוץ מן הפיזור שנתפזרו בבחי' נוגה (ומה שכתוב בעץ חיים דהנשמה עצמה אינה צריכה תיקון ולא ירדה בעוה\"ז רק לברר לבושי נוגה כו' ובכאן א' ואספת דגנך שהן הנשמות כו' הכל ענין א' שאין הנשמה עצמה צריכה תיקון כי היא בשרש עולם התיקון דחכמה כח מה כו' ואינם ניצוצות דתוהו שנפלו בשבירה שמזה נעשה בחי' לבוש לנשמה הוא שצריך קיבוץ ואסיפה והוא מה שגם נפש האלקי' נתפזרו חלקי הניצוצות שהן הלבושי' שלה ברצונות הזרו' דנה\"ב ונקר' לבושי' צואי' כו' וצריכי' בירור ותיקון אבל היא עצמה אינה צריכה תיקון כי לא נטמאה בטומאת הלבושי' שלה וכמה שכתוב בזוהר ונפש כי תחטא תווהא הוא כו' אדרבה ירדה לברר לבושים דנוגה כי בחכמה אתברירו דוקא כו' וד\"ל) אבל כשישראל עושין רצונו של מקום מבעל הרצון א\"צ לעבודה זו דקיבוץ ואספת דרפ\"ח כו' כי הרי הן למעל' ומדריג' שלמעלה מבחי' הבירורים לגמרי כמה שכתוב לע\"ל ואת רוח הטומאה אעביר לגמרי מה שאין כן עכשיו שצריכין עדיין לברר לרפ\"ח כו' ולאהפכא חשוכא לנהורא כו' ע\"כ נאמר ואספת דגנך כו' וד\"ל:\n(סא) <b>אך</b> עדיין אין זה מובן דא\"כ אין הדבר תלוי בעושין רצונו ש\"מ או אין עושין כו' אלא בתשלו' כל הבירורי' דרפ\"ח כו' דלע\"ל שיושלם כל הבירורים דרפ\"ח כו' ואין צריך לברר עוד על כן לא יצרכו אז לעבודה זו דואספת דגנך כו' ועכשיו קודם תשלום הבירור צריכין הן לברר בעצמם ולכך נאמר ואספת דגנך כו' ומה זה ענין לעושין רצונו של מקום או אין עושין כו' או לאהבה דבכל מאדך דוקא כו' וגם יש"],[2500660572,"להבין בזה גופא דלעתיד לבא אין צריך לעבוד עבודת הבירורים כלל משום שנא' ואת רוח הטומאה אעביר כו' א\"כ מה זה שנ' ועמדו זרים ורעו כו' הרי צריך לעבודה על כל פנים רק שלא יהיה עול העבודה בעצמו אלא על ידי אחרים וזה פלא לכאורה שזה סותר לגמרי עיקר ענין הנ\"ל בהפרש שבין עכשיו לעתיד לבא כו'. והנה להבין זה יש להקדי' תחלה ענין א' הידוע בע\"ח שיש ב' מדריגות א' בחי' גדלות המוחין והב' בחי' קטנות המוחין כו' וזהו עיקר ההפרש בין עכשיו לע\"ל דעבודת ישראל עכשיו הוא בבחי' קטנות המוחין וע\"כ נק' אין עושין רצונו ש\"מ וז\"ש ואספת דגנך שהוא בחי' עבודה שבקטנות כו' אבל לע\"ל יהי' בחי' עבודה דישראל בבחי' גדלות המוחין כמ\"ש ומלאה הארץ דעה כו' כי כולם ידעו אותי כו' ובמשיח נאמר ונחה עליו רוח ה' רוח חכמה ובינה כו' מפני שנק' עושין רצונו של מקום ולזה לא ישפילו א\"ע בעבודה דקטנות זו דואספת כו' לברר בירורי' כו' אלא אומות העולם יעבדו עבודה זו דואספת כמ\"ש ועמדו זרים כו' ולא שיעבדו אומות העולם בשביל עצמם אלא בשביל ישראל דוקא וכמה שכתוב ורעו צאנכם דוקא כי לעתיד לבא שיהי' עליות לישראל ולעמוד במדריגה דבחי' גדלות המוחין דמשיח כו' ממילא יהיו הגרים דאומות העולם כמ\"ש ונהרו אליו כל הגוים כו' עומדים רק במדריגה דישראל עכשיו שהוא בעבודת הבירורי' כו' וגם זה לא בשבילם אלא בשביל ישראל ואע\"פ שלא יהי' לע\"ל בחי' בירורים דרפ\"ח כו' שנפלו בשבירה כי הרי יבורר הכל כמ\"ש ואת רוח הטומאה כו' אבל מ\"מ צריך לעבודה כזאת אך במדריגה גבוה יותר והוא מ\"ש ועמדו זרים ורעו צאנכם ובני נכר אכריכם הרי יהיה חרישה וזריעה ובצירה כו' אבל לא לברר הטוב מן הרע כעבודה דעכשיו מאחר שנאמר ואת רוח הטומאה אעביר כו' אלא במדריג' עליונה ביותר וגם זאת"],[2500660573,"בשביל ישראל דוקא ובזה מתורץ הכל וד\"ל:\n<b>וביאור</b> הדברים הנה ידוע בענין מאלמים אלומים כו' שיש ב' מיני בירורי' א' בחי' בירור דבחי' ב\"ן כו' שזהו הנקרא בחי' ביטול היש לאין מעולם הפירוד לעולם היחוד כו' וזהו בחי' בירורים דרפ\"ח כו' כעה\"ד טוב ורע כו' אבל בחי' בירור שני הוא בירור אחר בירור שלאחר שכבר נברר הכל בבחי' ביטול היש לאין חוזר ועולה ונכלל בבחי' אין עצמו והוא בחי' בירור מ\"ה ומזה נמשך בחי' המשכת אא\"ס באצי' תמיד בבחי' ביטול העצמי דשם מ\"ה כו' ולא בחי' ביטול היש כלל וכמ\"ש במ\"א וזהו קמה אלומתי בחי' בירור ב' דיוסף בחי' יסוד ז\"א דאצי' ותשתחווינה לאלומתי כו' הרי גם בבחי' ביטול דמ\"ה שייך לשון עבוד' מאחר שנקרא אלומותי כו' רק שאין זה ביטול היש הנפרד כו' אלא בחי' ביטול האמיתי כמו ענין תורתו אומנתו שפטור מן התפלה שאינו רק ביטול היש כו' וזהו בחי' העבודה דישראל שיהיה בימות המשיח גם שיבוער הרע מכל וכל והוא בחי' ביטול היש אבל בבחי' מ\"ה דאצי' הרי שייך בחי' עבודה ג\"כ כנ\"ל וזהו בחי' עבודה שבגדלות המוחין דחכמה בחי' מה העצמי כו' (וז\"ש במשיח והריחו כו' דמורח ודאין בבחי' חוטמא דע\"י ששרשו מגיע במל' דא\"ס נשמתא דפרחא מחי העולמים שרש ומקור לג\"ר דא\"ק כו' וזהו מאד כנ\"ל וזהו למעלה גם מעבודה דגדלות המוחין דח\"ע כי זהו מבחי' פנימיות ומקור התענוג הפשוט ורצון הפשוט כו' כידוע ומבואר במ\"א) אבל בחי' עבודה שבקטנות המוחין שהוא ביטול היש הנפרד לאין כמו מאלמים אלומים כו' מלאכה זו נעשית ע\"י אחרים וז\"ש ועמדו זרים כו' שיהיו הגרים דאוה\"ע במדריגת עבודה דישראל עכשיו כנ\"ל ואע\"פ שלא יהיה לעולם בחי' נפרד כלל וא\"כ איך שייך עבודה דקטנות לעולם גם בזרים כו' הענין הוא דעבודה דקטנות דלע\"ל ג\"כ למעלה הרבה מבחי' הבירורים"],[2500660574,"דרפ\"ח עכשיו כי אז יהיה העבודה דקטנות בבחי' בירור דנוג\"ה דאצי' שאין שם בחי' רע כלל כמ\"ש לא יגורך רע כו' רק בחי' ביטול והעדר הרגשת עצמותו לבד כמה שכתוב במ\"א בפי' ראומה ראו מ\"ה כו' וזהו גם כן על ידי זרים שהן הגרים שיעבדו ויתקנו לבחי' היש דנוגה דאצי' להביאו לבחי' אין ומ\"ה דאצי' כו' וגם זה לא בשביל עצמם אלא יהיו טפלי' ובטלי' לישראל לעבוד עבודתם וזה שאמר ורעו צאנכ' דוקא שלא יסתיר לישראל בבחי' גדלות המוחין הנ\"ל בבחי' היש דנוג\"ה דאצי' ואין לישראל לעבוד בעצמ' בחי' קטנו' עבודה כזו ג\"כ כמ\"ש לעבוד עבודתו נכריה עבודתו כו' אלא מלאכה זו נעשית על ידי זרים מאומות העולם שיעבדו בשבילו ובעבור עבודתם לישראל נכללו ונטפלו לישראל וזהו עליי' שלהם משא\"כ כשהיה בחי' דבר נבדל בפ\"ע הרי הן בבחי' נוג\"ה גם לאחר הבירור שלהם דכתיב אז אהפוך אל העמים שפה ברורה כו' וד\"ל. וזהו שרשב\"י שתורתו אומנתו בבחי' בירור הב' שבמ\"ה דאצי' אמר אפשר אדם חורש וזורע כו' אלא בזמן שישראל עושין רש\"מ מלאכתן נעשית ע\"י אחרים כמ\"ש ועמדו זרים כו' דבעושין רש\"מ תליא מלתא ולא מצד תשלום הבירורים לע\"ל אלא גם עכשיו כשעושין כו' לפי שאין פי' עושין רש\"מ בקיום המצות שהוא הבירורים דביטול היש לבד אלא הפי' הוא מבחי' מקור הרצון הפשוט שהוא בעל הרצון שמשם עושין רצונו של מקום ולא בבחי' ביטול יש נפרד אלא בחי' הב' דבחי' מ\"ה וגם לזה שייך עבודה דבירור דנוג\"ה דאצי' וכנ\"ל אם אפשר אדם חורש כו' אלא זה נעשה על ידי אחרים ג\"כ כנ\"ל והיינו ע\"י אהבה דבכל מאדך וכמ\"ש רשב\"י בחד קטירא אתקטרנא כו' וכמ\"ש במ\"א וד\"ל:\n(סב) <b>והנה</b> להבין בתוס' ביאור ענין הנ\"ל דועמדו זרים כו' יש להקדים תוס' ביאור בענין בחי' קטנות וגדלות הנ\"ל ע\"ד העבודה בתפלה. דהנה"],[2500660575,"ידוע ביאור בחי' מוחין דגדלות בתפלה היינו בחי' ההתבוננות בעצמות אא\"ס ב\"ה שלמעלה מכל ההשתלשלות דאבי\"ע איך שאין עוד מלבדו וכולא קמיה כלא כו' וזהו דאימא מקננא בכורסייא להיות מקור לנשמות בג\"ע שיהיו משיגים ומתבונני' בעצמות זיו השכינה בחי' מל' דאצי' וזהו בחי' בינה שבמל' ושרשו למעלה בבחי' בינה דאצי' שבה נקרא מבין ולא בבינה ידיעא כידוע וזהו בחי' גדלות המוחין וכמ\"ש לפי שכלו יהולל איש על דרך משל איש ששכלו גדול מדותיו בבחי' הגדלות להתפעל בהתפעלות מדות שכליות מה שאין כן התינוק ששכלו קטן התפעלות מדותיו בבחי' הקטנות בענינים קטנים כמה שכתוב במקום אחר. וכך בענין התפעלות בהתבוננות גדלות ה' יש בזה ב' מדריגות הא' התפעלות המדות מצד התבוננות עצמות אור אין סוף שלגדולתו אין חקר בעצמותו כנ\"ל וממיל' גם בחי' המדות שמתפעלי' מזה זהו גם כן בעצמו' אור אין סוף ע\"כ נקרא מוחין דגדלות שבמדות כאיש גדול בשכל שמתפעל מדבר גדול כו' אבל התפעלות המדות מהתבוננות ההשתלשלות מאור אין סוף בעולמות לבד זהו בחי' קטנות המוחין שבמדות כמשל תינוק שמתפעל משכל קטן כו' ונקרא בחי' מוחין דיניקה כמשל התינוק שיונק שמדותיו בתכלית הקטנות כידוע וזה ענין בחי' הבירורים דרפ\"ח כו' התפעלות ביטול היש לאין הבא מהתבוננות ההשתלשלות מאין ליש כו' ואין זה ערך כלל לבחי' התפעלות הנשמות מזיו מהות ועצמות אור האלקי כו' בגן עדן העליון וכך עד רום המעלות ששרש זה הוא בבחי' בינה להבין בעצמות איך הוא ומהו כו' כמה שכתוב במקום אחר וד\"ל. והנה ידוע ששרש השבירה הוא בבחי' ב\"ן דז' מלכים דתוהו והוא בחי' קטנות המוחין ביותר וכאשר ירדו ונפלו למטה מטה בעולם הבריאה היינו בחי' קטנות דשם אלקים המצמצם ביותר וזהו שרש בחי'"],[2500660576,"נוג\"ה דבריאה יצירה עשיה כידוע. ולהיות כן כאשר בחי' היש הנפרד דנוגה בא בבחי' הבירור להעלותם למעלה בבחי' ביטול היש לאין כנ\"ל ה\"ז בחי' קטנות העבודה ביותר כמו על דרך משל עבודה פחותה שאדם עובד לרבו כמו לבשל קדירה או לתקן דברים פחותים שבבית כפכים קטנים וכה\"ג וכמ\"ש במקום אחר ואע\"פ שבחכמה אתברירו להבדיל הטוב מן הרע כו' והוא ע\"י התבוננות דהשתלשלו' מאין ליש שמזה מתפעל הנברא להיות בבחי' ביטול היש הנפרד לאין כנ\"ל א\"כ גם בחי' חכמה זו היא בבחי' קטנות המוחין לעבודה קטנה כזאת כמשל בישול הקדירה שאין צריך שכל גדול לזה כלל כו' והוא בחי' שם ב\"ן המברר ונקרא בהמה גי' ב\"ן וכמ\"ש בזהר ע\"פ מצמיח חציר לבהמה בחי' בהמה רבא דרביעא על אלף טורין ושתת לון בגמיעא חדא שהן המלאכים שנקר' חציר שעולין מבירורי נוג\"ה ונכללים בבחי' מל' שנקרא בהמה כשהוא בבחי' הקטנות כמ\"ש דוד ואני בהמות הייתי עמך שהוא בחי' דו\"ר טבעיים כמו משל מדות התינוק בימי היניקה וכה\"ג כנ\"ל וד\"ל:\n(סג) <b>והנה</b> כל משך זמן הגלות עיקר העבודה דכנ\"י הוא בבחי' מוחין דקטנות שהוא רק לברר בירורי נוג\"ה לאהפכא חשוכא לנהורא כו' וגם שבחכמה אתברירו אבל הוא בבחי' קטנות מאד וזהו מ\"ש בזהר דבזמן הגלות עיקר העבודה בתיקון ספיחי השדה לבד כי אין יחוד פב\"פ בזמן הגלות כו' וענין הספיחים הוא אשר צומח מן הארץ בבחי' מותרות ובלא זריעה כלל כו' כמ\"ש במקום אחר בביאור המאמר דהאי גננא כו' והיינו ביאור הפסוקים ונתתי מטר כו' ואספת דגנך כו' ואח\"כ ונתתי עשב בשדך לבהמתך ואח\"כ ואכלת ושבעת כו' שבחי' עשב אשר בשדה עליונה הן הן בחי' הספיחי' שבשדה העליונה הנק' חקל תפוחין כו' בחי' מל' דאצי' שנקרא חקל תפוחין קדישין כמ\"ש"],[2500660577,"כריח שדה אשר ברכו ה' כו' והעשב שבשדה זו הן הן נשמות הגרים מאומות העולם שהן ניצוצי קדושה שנתפזרו בע' שרים דנוג\"ה ומשם עולין וצומחין בשדה העליונה כו' והן הנקרא ספיחי השדה הזאת וכמ\"ש ונספחו על בית יעקב כו' וכמ\"ש במ\"א וד\"ל. וז\"ש עשב בשדך לבהמתך בחי' בהמה היא בחי' ב\"ן דקטנות המוחין הנ\"ל וכמ\"ש מצמיח חציר לבהמה כנ\"ל ואח\"כ ואכלת ושבעת וברכת כו' שהוא בחי' מוחין דגדלות שבחכמה כמ\"ש במ\"א בענין אכילת אדם ואכילת מזבח כו' וד\"ל. אך הנה לע\"ל יהיה עבודת ישראל בבחי' מוחין דגדלות הנ\"ל דגם שנאמר ונגלה כבוד ה' וראו כל בשר כי מלאה הארץ דעה את ה' דמשמע גם אוה\"ע בכלל וכמ\"ש ונהרו אליו כל הגוים כו' וכתיב אז אהפוך אל עמים שפה ברורה כו' לעבדו שכם א' כו'. הנה עם כל זה יהיה הפרש גדול בין ישראל לאומות העולם דבישראל נאמר כי עין בעין נראה אתה הויה כו' וראיה לזה ממה שמצינו שיהיו אומות העולם טפלים ובטלים לגבי ישראל בתכלית הביטול כמה שכתוב והיו מלכים אומנייך ושרותיהם מניקותייך כו' וכהאי גוונא מה שכתוב ועמדו זרים ורעו צאנכם כו' כי ישראל יראו עין בעין בעצמות אור אין סוף ב\"ה ממש בלי לבוש והסתר כלל רק כמו שהוא למעלה ממש בעצמותו יבא להם בגילוי למטה על כן יהיה עבודת ישראל אז בבחי' מוחין דגדלות הנ\"ל להיות נהנין מזיו העצמות דאור אין סוף כנ\"ל ממש כי התבוננות שלהם יהיה בעצמות ממש שלמעלה מכל ההשתלשלות דסובב וממלא כו' ולזאת לא יעבדו אז בחי' קטנות העבודה הנ\"ל דונתתי עשב כו' ביטול היש לבד שמצד השביר' כי לעתיד לבא יבוררו כל ניצוצות הקדושות שנפלו בקליפה ויוציאו מהם כל הטוב עד שלא ישאר רק הפסולת הגס יותר ויזרוק חוץ לאיבוד וכמארז\"ל לעתיד לבא ישחוט ליצה\"ר כו' וד\"ל. וגם לא יעבדו"],[2500660578,"בחי' עבודה השנית שנקר' בירור אחר בירור שהוא בחי' אכילת אדם שאחר אכילת מזבח כו' כנ\"ל בענין ואכלת ושבעת כו' (וכמ\"ש במ\"א בענין ואכלתם אכול כו' והיינו בחי' בירור הב' דבחי' מ\"ה הנ\"ל כמו ענין תורתו אומנתו כמ\"ש למעלה באריכות) שהרי מה שאמר ואספת דגנך כו' ואכלת ושבעת הכל כשאין עושין רצונו של מקום שהוא בזמן הגלות כידוע אבל לע\"ל שנקרא עושין רצונו של מקום לא יעבדו גם עבודה זאת דבחינת אסיפת הדגן לאכול אכילת אדם כו' כי יהי' לע\"ל במעלה ומדריגה יתירה מאד נעלה שהוא למעלה מבחי' הבירורים לגמרי דהיינו למעלה מכל בחי' מלאכה ועבודה לגמרי כו' והענין הוא על דרך המבואר במקום אחר בהפרש שבין תפלת החול לתפלת השבת שתפלת החול הוא בשביל איזה תיקון ובירור להפוך מרע לטוב או לברר בטוב עצמו כו' אבל בשבת בורר אסור ואין שום מלאכה ועבודה בשבת בתיקון ובירור כלל אלא רק בחי' התפעלות עצמיות שמצד עצמיות אור אין סוף כמו שהוא שלא מצד ההשתלשלות כלל כו' והתפעלות עצמיות זאת הוא בחינת תענוג עצמו שמתענג על ה' מצד עצמותו דוקא כמה שכתוב אז תתענג על ה' ממש כמו שהוא למעלה מכל ההשתלשלות כנ\"ל וד\"ל. ולא בשביל להוליד מהתפעלות זו בחי' עבוד' כלל גם לא עבודה ובירור הב' דבחי' מוחין דגדלות שבחכמה שנקרא כח מה שנקרא אכילת אדם כו' (וכמה שכתוב במקום אחר בפי' הזהר בפסוק באתי לגני אכלתי יערי כו' אבל באתריה לאו אורחי' למיכל כו' שזהו בבחי' פנימיות הכתר בכלל שהוא בחי' מל' דא\"ס שבכתר דא\"ק בכלל דהיינו פי' עושין רצונו של מקום בכלל כנ\"ל וד\"ל) וכך יובן בבחי' עבודה דישראל לע\"ל שיהיו רק נהנין מזיו העצמות בלי עבודת מלאכה כלל והוא הנק' בחי' מוחין דגדלות שלמעלה מכולם וגם עבודה"],[2500660579,"הב' דבחי' בירור הב' דבחי' מ\"ה הנ\"ל נק' בחי' קטנות לגבי עצמיות התענוג הזה שאינו נק' בשם מלאכה ועבודה כלל כו' רק אוה\"ע יעבדו אז בחי' עבודה זו שנק' מוחין דגדלות עכשיו שהוא בירור אחר בירור הנ\"ל והיינו כל אסיפת הדגן וכה\"ג וז\"ש ועמדו זרים כו' וד\"ל.\n<b>(ונמצא</b> מובן מכל הנ\"ל שסדר המדריגות בעבודת הבירורים עכשיו ולע\"ל כך הוא העבודה הראשונה שהוא בחי' הקטנות ביותר היינו עבודה לברר לבחי' נוג\"ה דבי\"ע שנק' יש נפרד כו' וזהו מאלמים אלומים דשבטים דבריאה ויצירה כו' כנ\"ל והב' בחי' בירור דנוג\"ה דאצי' שהוא העדר הרגשת עצמו כו' שזהו עבודת אוה\"ע לע\"ל בשביל ישראל כמ\"ש ועמדו זרים כו' והג' הוא בחי' בירור הב' דבחי' מ\"ה ביטול האמיתי והעצמי בענין תורתו אומנתו כו' והוא כמו בחי' עבודה דיוסף שא' קמה אלומתי כו' כנ\"ל וכמו רשב\"י שא' אפשר אדם חורש כו' שזהו כדוגמא דלע\"ל כשיהיו ישראל עושין רצונו כו' וד\"ל. והד' הוא בחי' עבודה דישראל לע\"ל שהוא בחי' מוחין דגדלות שבעצמות אא\"ס שלמעלה גם מבחי' גדלות המוחין דבירור הב' דבחי' מ\"ה הנ\"ל וד\"ל):\n(סד) <b>ובכל</b> הנ\"ל יובן מ\"ש והיו מלכים אומניך ושרותיה' מניקותיך כו'. דהנה מבואר למעלה דבחי' קטנות העבודה בבחי' מוחין דיניקה שעכשיו בזמן הגלות הוא עיקר העבודה דכנ\"י שהוא לברר בירורי נוג\"ה כנ\"ל הנה לעתיד לאחר תשלום הבירורים דרפ\"ח כנ\"ל ויבוררו הכל יהיה בחי' המשכת מוחין דיניקה מבחי' ז' מלכים דתוהו וע' שרים דנוג\"ה שיהיה לעתיד אחר הבירור כמ\"ש ונהרו אליו כל הגוים כו' כנ\"ל וזהו ושרותיהם מניקותיך ממשיכים בחי' מוחין דיניקה לכנ\"י כו' כי ידוע דלאחר הבירור דב\"ן דתוהו שהוא בחי' מלכים כו' עולה לבחי' ס\"ג שהוא בחי' ז\"ת דבינה שהיה בו עיקר השבירה כידוע בענין ע' רבתי כו' וידוע דדם נעכר ונעשה חלב כו' כך מבחי' בירור הגבורות"],[2500660580,"דב\"ן דתוהו כשעולין בשרשם בבחי' ס\"ג נעשה בחי' חלב דיניקה שהוא מבחי' קטנות המוחין דבינה כו' וזהו ושרותיהם מניקותייך להמשיך בחי' מוחין דיניקה ולא יצטרכו לעבוד בעצמם כלל כו' וד\"ל. אך בחי' מוחין דיניקה לעתיד יהיה גבוה הרבה במדריגה גם מבחי' מוחין דגדלות דעכשיו מאחר שיבורר בחי' ב\"ן לגמרי לעתיד לבא ולא יצטרך לבירור דביטול היש הנפרד א\"כ מה שיהיה לעתיד לבא בחי' דם נעכר ונעשה חלב כו' הכל הוא בבחי' בינה שהוא בבחי' ס\"ג שלמעלה מבחי' מ\"ה דעכשיו כו' (וזהו ושרותיה' מניקותי' כמו באר חפרוה שרים שהן או\"א שממשיכים בחי' מוחין דגדלות במדות עכשיו אבל לע\"ל לא יהיה בחי' שרים רק בבחי' מוחין דיניקה לפי שבחי' התוהו למעלה מבחי' התיקון ומה שבתיקון נק' מוחין דגדלות נק' בחי' מוחין דיניקה בבחי' התוהו לאחר הבירור"],[2500660581,"שיהיה בחי' ב\"ן בבחי' ס\"ג כמה שכתוב א\"ח עט\"ב כו' וד\"ל). ובכל זאת מובן בתוספת ביאור ענין ועמדו זרים כו' שזהו כשעושין רצונו של מקום דוקא שאז יעבדו אומות העולם בחי' עבודה דישראל עכשיו שהוא ואספת דגנך כו' אבל ישראל עבודתם בבחי' מוחין דגדלות הנ\"ל שהוא בחי' עצמות אור א\"ס ב\"ה שבפנימיות הכתר שבכתר הנק' רעוא דכל רעוין כו' שזה נק' עושין רצונו של מקום כנזכר לעיל באריכות אבל כשאין ישראל עושין רצונו של מקום היינו בזמן הגלות שעבודתם בבחי' הקטנות כנ\"ל אז נאמר ואספת דגנך כו' ולכך לא נאמר בכל מאדך בפרשה שנייה לפי שבחי' בכל מאודך מגיע בעצמות אא\"ס שהוא בלי גבול כו' וזה לא יהיה רק לעתיד דכתיב במשיח וגבה מאד מטעם הנ\"ל וד\"ל:\nהשלמה לשער התפלה"],[2500660582,"<h3>שער התפלה. ביאור לתורה דלעיל ע\"פ אחרי ה' כו'</h3>\n<b></b><b>ביאור לתורה דלעיל ע\"פ אחרי ה' כו'</b>\n<b></b>[(מב)] ולהבין בתוס' ביאור לענין הנ\"ל בפי' ימינך ה' ב\"פ ימין לנגד ב\"פ שמאל דשמאלו תחת כו'. הנה תחלה יש להבין בתוס' ביאור ענין עליות העולמות עד מספר נו\"ן אלפים יובלות הנ\"ל בפי' ברוך חי לעד כו' (באות י\"ב) ויש להקדים לזה הקדמה כללי' הנז' בע\"ח דבעצמו' אוא\"ס עד גם בחי' מל' דא\"ס שלפני הצמצום הראשון כו' אין אנו רשאין לדבר בו בדרך פרט כי לית מח' תפיסא בי' (אפי' מח' דא\"ק שהרי מבחי' מל' דא\"ס אחר הצמצום נעשה בחי' כתר דא\"ק בראשית הקו וחוט כו' כידוע) ומ\"ש מלכותך מלכות כ\"ע הרי מדברים גם במל' דא\"ס שנק' מלכותך בכלל אין הכונה בדיבור זה שמשבחים ומפארים בתפלה שהוא בעצמו' אא\"ס דוקא כמ\"ש לך ה' הממלכה דקאי גם על בחי' מל' דא\"ס כו' כי בתפלה הרי א' אלי\"ו ולא למדותי\"ו כלל כו' רק הכונה בדיבור דיבור זה הוא הבא בגילוי ההשגה ומשום שנא' במופלא ממך אל תחקור כו' וגם בחי' מל' דא\"ס נק' מופלא סדכ\"ס להיותו מבחי' האחרונה שבעצמו' אא\"ס כו') וגם בבחי' ג\"ר דא\"ק עדיין הוא למעלה מכל ההשתלשלות דאבי\"ע כידוע דכל תחלה ושרש כל ההשתלשלות והתלבשות הפרצופי' דע\"י וא\"א ואו\"א וזו\"נ דבי\"ע הכל הוא רק מן בחי' נה\"י דא\"ק ולמטה (כמבואר בציור האילן) עד בחי' עקביי' דא\"ק שמסתיים בסוף העשי' (וכמו באדה\"ר שהי' קודם החטא כדוגמת בחי' א\"ק שנק' אדם דבריאה וראשו בבריאה וגופו ביצי' ורגליו בעשי' כך גם כל בחי' שרש כל האצי' נק' רק בחי' עשי' בכללו' והוא רק מבחי' נה\"י דא\"ק וכמ\"ש בלק\"ת בפי' אם תשיב משבת רגלי\"ך שהוא בחי'"],[2500660583,"נה\"י דא\"ק שע\"ז א' אל יצא איש ממקומ\"ו ביום הז' כו' וד\"ל) ולהבין טעם הדברים הללו צריך להקדים עיקר ענין ההפרש שבין בחי' עצמו' אא\"ס שקודם הצמצום הראשון (הנק' מקו\"פ כו') ובין בחי' הארת הקו וחוט שאחר הצמצום שזהו שרש ומקור כללו' כל ההשתלשלות מבחי' ג\"ר דא\"ק עד סוף העשי' בבחי' מל' דמל' דעשי' כידוע להיות ידוע דבחי' עצמו' אא\"ס ממש אע\"פ שנק' רק בשם אור בלבד אבל הוא בחי' אור עצמי שהוא פשוט בתכלית הפשיטות כמו עצמו' הא\"ס ממש כי הוא למעלה מבחי' אור השפעה לחוץ מן עצמותו עדיין והגם שהוא בא בבחי' גילוי אור אבל הוא מתגלה כמו שהוא בבחי' עצמותו ממש שע\"ז אנו או' אתה אחד ושמך אחד אתה קדוש ושמך קדוש שהוא בבחי' שמו העצמי עדיין שהוא קדוש בקדושת עצמותו הפשוט בתכלית וכמארז\"ל קודם שנברא העולם הי' הוא ושמו בלבד פי' בלבד הכל בבחי' העצמו' עדיין שאין עוד מלבדו כלל (וכמ\"ש בע\"ח דקודם הצמצום הי' אוא\"ס ממלא את כל החלל כו' ומבואר בקונטרס ההתבוננו' באות י' וי\"א באריכות שזהו כדמיון בחי' התכללות כח התנועה בעצם החי וככח ובחי' גילוי החיו' להחיות שכלול בעצם הנפש) והגם שבחי' אור עצמו' הזה יש בו בבחי' העלם העצמו' בחי' רצון וחכ' ומדו' עד בחי' מל' דא\"ס (כמבואר בענין יחיד ואח\"ד וקדמון (באות יו\"ד שם) והכל בבחי' עצמו' אא\"ס שקודם הצמצום) כמו כשעלה ברצונו הפשוט כו' עד מל' דא\"ס שהוא הרצון ומח' דאנא אמלוך כו' הכל הוא נחשב מבחי' עצמו' אוא\"ס והכל הוא בבחי' א\"ס ממש (וזהו דשמו גי'"],[2500660584,"רצון כידוע קאי גם בבחי' שמ\"ו הגדו\"ל בכלל שהוא כללו' עצמו' אא\"ס שנק' שמו העצמי וגם בדרך פרט הוא רצון הפשוט עד מל' דא\"ס שנק' ג\"כ שמו הגדול לגבי ההשתלשלות משום דבחי' מל' דא\"ס כבר נעשה מקור לראשית הקו כנ\"ל וז\"ש יהא שמי' רב\"א זה מברך בראשית הקו אחר הצמצום הראשון הנ\"ל להיות בא בסדר הג' בחי' ומדרגו' דבי\"ע שהן ג' מיני אדם א\"ק אדם דבריאה ע\"י וא\"א אדם דיצירה זו\"נ אדם דעשי' וזהו לעלם בחי' בריאה דהיינו בבחי' א\"ק ולעלמי עלמיא בחי' יצי' ועשי' שנכללו כולם בבחי' נה\"י דא\"ק בלבד כנ\"ל וכן ענין ברוך שאמר והי' העולם הנ\"ל (באות ז' וח') ובזה א' במופלא ממך כו' דלית מח' תפיסא בי' כלל כי בכל בחי' העלם העצמו' נק' סדכ\"ס אע\"פ שנק' בבחי' אור ושם בלבד וד\"ל אבל בחי' הארת הקו וחוט שאחר הצמצום הראשון הנ\"ל הוא הנק' אור הנבדל מן העלם העצמו' בשביל מקור לכללו' ההשתלשלות שם יש רשות לדבר כי יש בו שרש לבחי' פרטי השתלשלות עכ\"פ (וע\"כ גם הנשמו' שבגופים שמקבלים רק מבחי' מל' דמל' דעשי' יוכל לדבר גם בראשית הקו מאחר שהוא שרשם הראשון בבחי' א\"ק אדם דבריאה) (כי בחי' הקו הזה כולל כל מה שבא דרך פרט עד סוף העשי' עד\"מ מח' כללית שחושב בבנין כו' (כמ\"ש שם באריכות) וכמ\"ש במ\"א בענין וכל היצו\"ר לא נכח\"ד ממ\"ך כו') א\"כ הרי יש לכל פרט עד גם הפרט היותר אחרון בו שרש לשרש עכ\"פ) ולכך יוכל כל אדם להתבונן לפי השגתו בבחי' התפשטו' אור א\"ס זה מפני שאין לו ערוך כלל וכלל לגבי העלם העצמו' אע\"פ ששיער בעצמו כל מה שעתיד להיות בפועל כענין ברוך שאמר בעצמו"],[2500660585,"והי' כו' הכל עדיין בבחי' העלם העצמו' דלית מח' תפיסא בי' בהשגה כלל רק ע\"י התלבשותו באצי' ע\"י ד' אותיות דהוי\"ה וכה\"ג וכמו ויאמר ה' אל משה כו' (ומ\"ש לעתיד הנה אלוקינו ז\"ה לנוכח וכן ז\"ה אלי וגם א' עין בעין נראה אתה כו' וכך במ\"ת דכתי' וירד ה' כו' וכל העם רואים כו' הכל הוא ע\"י התלבשות העצמו' בק\"ו וחו\"ט רק בא ביותר מכפי המדה והצמצום הראשון כו' ובאמת כל בחי' עצמותו כמו שהוא ממש יתגלה לעתיד כמשי\"ת בסמוך דגם שנא' וע\"י יתיב כו' קאי בבחי' עתיקא דעתיקין סדכ\"ס שהוא בחי' תענוג שבעצמו' הפשוט ממש בבחי' מל' דא\"ס שנק' מלכות על\"ם דלא תשתני כלל וכידוע בענין ועד בחלופי אתוון דאח\"פ ממש להיות שגם בבחי' ההשגה דמח' אינו נתפס אבל בבחי' יחידה ממש בעצמו' התענוג דכנס\"י שנק' חפצי ב\"ה יהי' נתפס כנ\"ל באות א' וד\"ל).\n(מג) <b>אך</b> הנה לכאורה יש סתירה גדולה לכל הנ\"ל ממ\"ש מלכותך מלכות כ\"ע דקאי בבחי' מל' דא\"ס דוקא שהוא מקור הראשון לכל בחי' מל' ממל' דא\"ק עד מל' דעשי' ונק' מל\"ך מלכ\"י המלכי\"ם כו' כידוע ולעתיד כתי' במשיח ג\"כ ישכיל עבדי כו' וגבה מא\"ד שהן בחי' עליו' כל העולמו' עד שמאיר בחי' מל' דא\"ס ממש במל' דאצי' עד מל' דעשי' שיאיר במלכא משיחא כו' (והיינו דוד מ\"י חי וקיים כנ\"ל בפי' וע\"ד כו' וכמ\"ש במ\"א בענין ע' שנין דא\"ק כו') והרי זהו היפך ענין הנ\"ל דבהעלם עצמו' אא\"ס לית מח' תפיסא כו' וגם מפשט הכתוב משמע דמלכותך ממש שהוא בחי' מל' דא\"ס הוא מלכות כל עולמים דהיינו גם להיות בבחי' מל' דעשי' שרש עוה\"ז השפל ג\"כ כו' וכמ\"ש"],[2500660586,"אני ראשון ואני אחרון אנ\"י מל' דא\"ס ראשון לקו וחוט ואנ\"י זה ממש אחרון בסוף הקו במל' דעשי' שע\"ז אמר ראו כי אני אני הוא ממש ומבלעדי כו' באמציעותא כו' כמ\"ש במ\"א (ומ\"ש למעלה טעם ההפרש שבתפלה הוא שמבקשים אליו כו' זה אינו תירוץ כלל לענין הפשט שמלכותך מלכות כ\"ע ממש כנ\"ל וד\"ל) וזה סותר לכל סדר ההשתלשלות שנז' בע\"ח שאינו רק מבחי' נה\"י דא\"ק ולמטה כנ\"ל) אמנם לפ\"ז גם זה לא יובן מה שעיקר גילוי בחי' מל' דא\"ס למטה במל' דעשי' לא יהי' רק לע\"ל דוקא וכנ\"ל בפי' ישכיל עבדי כו' וא\"כ מה זה שא' מלכותך כו' דקאי גם עכשיו כנ\"ל אלא מוכרח לומר ששניהם אמת מצד שיש הפרש וחילוק איזה דבר בזה ובזה הטעם עצמו יתורץ ג\"כ סתירה דלעיל וד\"ל. והענין הוא כידוע ומבואר במ\"א בענין זכר רב טובך כו' בהפרש שבין בחי' עצם והתפשטו' שהוא בבחי' זיו ואור או כח התנועה וכהנ\"ל לבחי' העלם וגילוי שהתפשטו' מן העצם הוא דבר מחודש בין בעצם שממנו ומכחו באה ההתפשטו' בין בגופו של התפשטו' עד שיש שינוי בין קודם התפשטו' לאח\"כ כו' אבל בחי' גילוי ההעלם אין כל חדש כלל וכלל לא בעצם ההעלם וגם לא בגילוי עצמו בין קודם שנתגלה לאחרי הגילוי וגם עצם גופו של גילוי אינו מחודש כלל לגבי העצם כי ישנו לעצם בכל מהותו כמו שהוא בדבר שמתגלה לאחר הגילוי כמו קודם הגילוי בשוה ממש ויש לזה ה' דמיונות הא' מחיו' הנפש שבהעלם הבא בגילוי באיברי הגוף שאין זה נק' התפשטו' להיות נופל לשינוי אלא הוא בלתי שינוי גם לאחר הגילוי כקודם הגילוי ממש וראי' מגלגולים כו' והב' מכח הראי' בעין בסגרו העין או בפתחו"],[2500660587,"שאינו ענין גילוי מחודש לגבי עצם כח הראי' מאחר שהוא במהותו בסגירה כמו בפתיחה ממש בשעה כו' והג' מכח השכל להשכיל שההתחכמו' לא נק' התפשטו' דבר רק בחי' גילוי כמראה וגוון ולא יפול שינוי כלל בעצם כח השכל בגילוי המושכל כו' והד' משלהבת הקשורה בגחלת בהעלם ובא לידי גילוי ע\"י הכאה בצור וכה\"ג שבצור הי' החמימות בהעלם וגילוי הניצוץ הזה אינו בחי' מחודש כלל בעצם החמימות שבצור כו' והה' מן העלם המחשבה שבא לדיבור כו' והעולה על הכל הוא דמיון האמיתי הוא זה המשל מן המח' ודיבור שנק' חושך ואור בריאה ויצי' כו' והוא משתווה אל אמיתי' הענין לבא בחי' גילוי ההעלם למעלה שזהו שכתוב ישת חושך סתרו כו' שהוא בחי' הצמצום בעצמו דהיינו גליף גליפו בטה\"ע כו' שהוא מה שמשער בעצמו בכח מה שרוצה להיות בפועל הגילוי שהוא בבחי' הקו וחוט שנק' גילוי ההעלם דעצמו' כו' וד\"ל ולפ\"ז יובן ביותר ענין אני ה' לא שניתי בין קודם הצמצום לאחר הצמצום מאחר שנק' גילוי ההעלם כמובן בדמיונות הנ\"ל שאין זה מחודש ושינוי כלל לגבי העצמו' והיינו כמשל המטמון שמתגלה לעין הרואה שאין כל חדש כלל בגילוי זה לגבי עצם המטמון שהוא במהותו ממש בשוה בין קודם הגילוי בין אחר הגילוי וגם גופו של גילוי אינו ענין חדש* רק לגבי הרואה שהי' נעלם ממנו תחלה כו' וכמו\"כ ענין הגילוי בעצמו' אוא\"ס הנעלם בעצמותו כשבא אחר הצמצום לבחי' קו וחוט שאין בזה שינוי כלל וכלל"],[2500660588,"בעצמו ממהותו קודם הגילוי לאחר הגילוי דכמו קודם הגילוי הי' הוא ושמו בלבד כך אחר הצמצום עצמו כשבא לבחי' גילוי הוא ושמו בלבד בלי שום שינוי כלל וכלל גם בגופו של גילוי הקו הזה מראשו לסופו בסוף העשי' אינו ענין מחודש כלל לגבי העצמיות וד\"ל ובזה יובן מ\"ש מלכותך מלכות כ\"ע שהוא מל' דא\"ס במל' דעשי' עכשיו כמו לעתיד שיתגלה בחי' עצמיות ממש שוה לפניו ממש כעכשיו מאיר בכל עצמותו כמו שהוא עד מל' דעשי' כמ\"ש את השמים ואת הארץ אני מלא בשוה ממש וכמאמר לית אתר פנוי מיני' ממש רק שהוא בהעלם כמשל מטמון הנעלם כו' וכמובן בדמיון חיות הנפש בהעלמו בגוף או כמו כח הראי' וכח השכל כנ\"ל ומה שעכשיו אינו בגילוי למקבלים ולעתיד יתגלה למקבלים אין גילוי זה"],[2500660589,"שינוי ומחודש רק לגבי המקבלים בלבד אבל לא לגבי עצמותו כלל ולכך הוא אומר ראו כי אני אני הוא ממש וגם אומרים מלכותך מכ\"ע ממש אע\"פ שלגבי המקבלים ודאי בחי' מל' דא\"ס במל' דעשי' בא ע\"י כמה ריבוי השתלשלות והסתרים אך לגבי עצמותו אין זה הסתר כלל להיות הגילוי דלעתיד במל' דא\"ס במל' דעשי' ענין דבר מחודש כלל וכלל וד\"ל ובזה מתורץ הסתירה דלעיל דודאי שניהם אמת דבעצמו' אין למקבלים תפיס' כלל והגילוי דעצמו' למקבלים לא יהי' רק לע\"ל וגם זה אמת דמלכותך מכ\"ע עכשיו ג\"כ כמו לעתיד משום דלגבי עצמותו אין שינוי בזה ועיקר השינוי בין עכשיו לעתיד אין רק לגבי המקבלים בלבד כמשל גילוי המטמון וכהנ\"ל במשלים הנ\"ל וד\"ל."]]});
